///   4ff1a  mov  0xc(%esp),%eax         ; the axis_3d argument
///   4ff1e  mov  0x1e400,%esi           ; AE400
///   4ff24  lea  0x23d9(%esi),%edi      ; &str_9177[0]   (0x23d9 = 9177)
