    #[test]
    fn worm_segments_trail_the_head() {
        let planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        let things = vec![Thing {
            slot: 0,
            kind: ThingKind::Entity,
            class: 5,
            model: 0,
            x: 100,
            y: 100,
            dis_id: 0,
            swi_sz: 0,
            swi_id: 0,
            parent: 0,
            child: 0,
            par3: None,
        }];
        let mut w = World::new(planes, &things, 1, assets());
        let heads: Vec<_> = w.live_poses().into_iter().filter(|p| !p.segment).collect();
        let segs: Vec<_> = w.live_poses().into_iter().filter(|p| p.segment).collect();
        assert_eq!(heads.len(), 1, "one worm head");
        assert_eq!(segs.len(), 16, "sixteen body segments");
        assert_eq!(
            w.live_things().len(),
            1,
            "segments hidden from entity lists"
        );

        let p = PlayerPose::from_tiles(101.5, 14.0, 101.5, 0.0, 0.0, 0.0);
        for _ in 0..60 {
            w.tick(p, PlayerCommand::default());
        }
        let head = w
            .live_poses()
            .into_iter()
            .find(|p| !p.segment)
            .expect("head alive");
        let segs: Vec<_> = w.live_poses().into_iter().filter(|p| p.segment).collect();
        // Awake movement strings the body out: the first segment sits
        // its follow distance behind the head, not on it.
        let d0 = (segs[0].x - head.x).abs() + (segs[0].z - head.z).abs();
        assert!(
            d0 > 0.05,
            "segment 0 trails the head (offset {d0}, head at {:?})",
            (head.x, head.z)
        );
        let distinct: std::collections::HashSet<_> = segs
            .iter()
            .map(|s| ((s.x * 256.0) as i32, (s.z * 256.0) as i32))
            .collect();
        assert!(
            distinct.len() > 8,
            "segments spread out ({} distinct positions)",
            distinct.len()
        );
    }

    #[test]
    fn asleep_crowds_do_not_pack_and_accelerate() {
        // WANDER's scans are awake-gated in the original — a distant
        // crowd must never form packs and ride the unbounded pack
        // accel.
        let planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        let bee = |slot, x, y| Thing {
            slot,
            kind: ThingKind::Entity,
            class: 5,
            model: 1,
            x,
            y,
            dis_id: 0,
            swi_sz: 0,
            swi_id: 0,
            parent: 0,
            child: 0,
            par3: None,
        };
        let things: Vec<Thing> = (0..8)
            .map(|k| bee(k, 100 + (k % 3) as u16, 100 + (k / 3) as u16))
            .collect();
        let mut w = World::new(planes, &things, 1, assets());
        // Player far away the whole time (> 24 tiles: asleep).
        let far = PlayerPose::from_tiles(10.0, 14.0, 10.0, 0.0, 0.0, 0.0);
        for _ in 0..3000 {
            w.tick(far, PlayerCommand::default());
        }
        let before: Vec<_> = w.live_poses();
        w.tick(far, PlayerCommand::default());
        let after: Vec<_> = w.live_poses();
        // Bee speed = 50 engine units/tick ≈ 0.195 tiles; pack
        // catch-up adds a bounded +16 per chain level. The runaway
        // failure mode reached many tiles per tick and kept growing —
        // anything near a tile/tick means it is back.
        for (b, a) in before.iter().zip(&after) {
            let d = (a.x - b.x).abs().min(256.0 - (a.x - b.x).abs())
                + (a.z - b.z).abs().min(256.0 - (a.z - b.z).abs());
            assert!(
                d < 1.0,
                "asleep bee moved {d} tiles in one tick (speed ran away)"
            );
        }
    }

    #[test]
    fn burrower_materializes_then_hides() {
        // m9's spawn sequence (sub_1CFF0): flame form 220 → transform
        // animation 237 → the type-201 lurking mound at state 55.
        let planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        let things = vec![Thing {
            slot: 0,
            kind: ThingKind::Entity,
            class: 5,
            model: 9,
            x: 100,
            y: 100,
            dis_id: 0,
            swi_sz: 0,
            swi_id: 0,
            parent: 0,
            child: 0,
            par3: None,
        }];
        let mut w = World::new(planes, &things, 1, assets());
        let near = PlayerPose::from_tiles(102.5, 14.0, 102.5, 0.0, 0.0, 0.0);
        let mut seen = Vec::new();
        for _ in 0..80 {
            w.tick(near, PlayerCommand::default());
            let t = w.live_poses()[0].type_index;
            if seen.last() != Some(&t) {
                seen.push(t);
            }
        }
        assert_eq!(seen, vec![220, 237, 201], "materialize sequence");
    }

    /// THE CRAB EGG DRAWS (player-reported: crabs multiplied out of
    /// thin air). The (10,52) egg's ctor assigns sprite-stats row 205
    /// — the grey cracked shell, art 228, and row 205 is the ONLY
    /// stats row that points at it — but the egg was missing from
    /// `drawable`, so it incubated its whole life invisible. The sim
    /// side was never wrong: mc1l32 is certified across its one egg
    /// (t=21644..22246) and the port's `type86` reads 205 there. The
    /// graded projection carries no `type86` lane, which is why
    /// certification could not see this.
    ///
    /// The paired negative is the guard that keeps the fix MC1-only:
    /// MC2's (10,52) is the invisible castle anchor.
    #[test]
    fn crab_egg_is_drawable_with_its_shell_sprite() {
        let mut w = flat_world();
        let egg =
            w.g.spawn_creator(52, 100 << 8, 100 << 8, 100)
                .expect("the egg spawns");
        assert_eq!(
            (
                w.g.ent[egg].class64,
                w.g.ent[egg].model65,
                w.g.ent[egg].type86
            ),
            (10, 52, 205),
            "the ctor's own labels and sprite row"
        );
        let pose = w
            .live_poses()
            .into_iter()
            .find(|p| p.slot == egg as u16)
            .expect("the egg is drawn");
        assert_eq!(pose.type_index, 205, "the pose carries the shell sprite");
        assert!(!pose.map_only, "retail plots it in-world, not map-only");
        assert_eq!(
            crate::mc1::sprite_stats::SPRITE_STATS[205].sprite_base,
            228,
            "row 205 resolves to the cracked-shell art"
        );
        // MC2's (10,52) is the castle anchor — an invisible controller.
        assert!(
            !drawable(GameId::Mc2, 10, 52),
            "the MC2 castle anchor must not acquire the egg's sprite"
        );
    }

    #[test]
    fn deterministic_across_runs() {
        let run = || {
            let mut w = flat_world();
            for t in 0..200 {
                let p = if (40..80).contains(&t) {
                    at_trigger()
                } else {
                    away()
                };
                w.tick(p, PlayerCommand::default());
            }
            (w.planes().height.clone(), w.live_things().len())
        };
        assert_eq!(run(), run());
    }

    // ---- combat ------------------------------------------------------------

    /// ⭐ EVERY MANIFESTATION BOLT IS BORN HOLDING ITS DEST TRIPLE, OFF
    /// THE CASTER'S RAW RECORD (round 154, w154b — the generalisation
    /// of w152l's Meteor-only stamp). `sub_56090` :65074-76 (CARPET.EXE
    /// VA 0x561B7-0x561E2: `lea 0x96(%ebx); lea 0x48(%ebp); movsl;
    /// movsw; push $0x4000; push +32; push +30; call sub_41EC0`) and
    /// the flat-projected `sub_567A0` :65358-62 (VA 0x568AC-0x568E7:
    /// `push $0x1000; push $0; push +30; call sub_41EC0; call
    /// sub_11F50; mov %ax,0x9a(%ebx)`) — the two shapes the table on
    /// [`Gen::mc1_stamp_bolt_dest`] lists, on the human arm. The
    /// triple is a raw-shadow lane (no OBS field carries `+150`), so
    /// this test is the pin: mc1l2 t=2 slot 197 and mc1l0-spells-galore
    /// are the corpus witnesses (every `(9,x) dest_x/dest_y/site_z`
    /// pair row on both takes gone, 2,591 → 0 and 342 → 0).
    ///
    /// NON-VACUITY: `MGC_NO_MC1_BOLT_DEST_STAMP=1` fails legs (a) and
    /// (b) at the 0/0/0 ctor default; `MGC_NO_MC1_EMIT_DETONATION_PAIR=1`
    /// fails leg (b)'s `+68/+69`; `MGC_NO_MC1_CASTLE_UPGRADE_BALL_NO_DEST=1`
    /// fails leg (c).
    #[test]
    fn a_manifestation_bolt_is_born_holding_the_casters_projected_dest() {
        let mut w = flat_world();
        w.set_dev_spells(true);
        w.grant_all_spells();
        // The record pose: raw z 3360, a live aim with pitch — the
        // muzzle lifts z by the carpet's half-height and steps 256 to
        // the hand's side, and NEITHER reaches the triple.
        let p = PlayerPose {
            x: (112 << 8) + 128,
            y: (116 << 8) + 128,
            z: 3360,
            heading: 300,
            pitch: 1990,
            speed: 40,
        };
        // (a) the fireball: raw axis stepped 0x4000 along (+30, +32).
        w.cast_fireball(p, true, 0);
        let bolt = (1..w.g.ent.len())
            .find(|&j| w.g.ent[j].class64 == 9 && w.g.ent[j].model65 == 0)
            .expect("the fireball arm mints its (9,0)");
        let mut want = (p.x, p.y, p.z);
        Gen::polar_step(&mut want, 300, 1990, 0x4000);
        let e = &w.g.ent[bolt];
        assert_ne!((e.x, e.y, e.z), (p.x, p.y, p.z), "the muzzle moved the bolt off the record");
        assert_eq!(
            (e.dest_x, e.dest_y, e.site_z),
            want,
            "fireball: `+150/+152/+154` = caster raw axis stepped 0x4000 along the live aim"
        );
        assert_ne!(want.2, p.z, "the pitched step moved z (the leg is not vacuous on z)");

        // (b) the earthquake lob: flat 4096 step, then the GROUND under
        // the dest replaces z (:65362 `sub_11F50`), and the machine's
        // own detonation pair 10/15 (VA 0x56840/0x56844).
        w.cast_projectile(6, p, true);
        let lob = (1..w.g.ent.len())
            .find(|&j| w.g.ent[j].class64 == 9 && w.g.ent[j].model65 == 2)
            .expect("the earthquake arm mints its (9,2)");
        let mut flat = (p.x, p.y, p.z);
        Gen::polar_step(&mut flat, 300, 0, 4096);
        let gz = w.g.ground_z(flat.0, flat.1) as i16;
        let e = &w.g.ent[lob];
        assert_eq!(
            (e.dest_x, e.dest_y, e.site_z),
            (flat.0, flat.1, gz),
            "earthquake: flat 4096 projection, z = the ground under it"
        );
        assert_ne!(gz, p.z, "the ground z is not the caster's z (non-vacuous)");
        assert_eq!((e.f68, e.f69), (10, 15), "earthquake `+68/+69` = (10,15) at the mint");

        // (c) the castle UPGRADE ball stamps nothing (:65904-08, the
        // `jbe` at VA 0x5771C jumps the create arm's stamp): bind a
        // castle first, then cast.
        let c = w
            .g
            .spawn_class3(2, p.x.wrapping_add(4000), p.y, 100)
            .expect("castle slot");
        w.g.ent[c].id24 = PLAYER_TARGET;
        w.g.castle_reg[0] = c as u16;
        assert!(w.cast_castle(p, true, None), "the upgrade cast mints its ball");
        let ball = (1..w.g.ent.len())
            .find(|&j| w.g.ent[j].class64 == 9 && w.g.ent[j].model65 == 10)
            .expect("the castle arm mints its (9,10)");
        let e = &w.g.ent[ball];
        assert_eq!(e.f69, 43, "bound castle ⇒ the UPGRADE arm");
        assert_eq!(
            (e.dest_x, e.dest_y, e.site_z),
            (0, 0, 0),
            "the upgrade ball's triple stays at NewEvent's 0 (mc1l2 t=567 slot 199)"
        );
    }

    /// Directly south of the combat worlds' creature (112,110),
    /// facing north (engine yaw 0 = -y): the fireball's line of fire.
    fn firing_line() -> PlayerPose {
        PlayerPose::level((112 << 8) + 128, (116 << 8) + 128, 3360, 0)
    }

    fn count(w: &World, class: u8, model: u8) -> usize {
        w.debug_pool()
            .1
            .iter()
            .filter(|e| e.class == class && e.model == model)
            .count()
    }

    /// Combat-test loadout: the Rapid Fireball firehose (23) on the
    /// left hand with the dev mana pin — the only hold-to-autofire
    /// spell, giving the 1-projectile-per-held-tick cadence the
    /// combat tests were written against. Invincibility pins the
    /// dev-player semantics these tests assume (damage totaled from
    /// tick 0, no death mid-fight); mortality has its own tests.
    fn rapid_fire(w: &mut World) {
        w.set_dev_spells(true);
        w.grant_all_spells();
        w.set_invincible(true);
        w.player.left = Some(crate::mc1::spells::SpellId(23));
    }

    /// A flat world holding one load-time creature and nothing else —
    /// no crater rims for a chaser to wall-death on.
    fn bare_creature_world(model: u16) -> World {
        let planes = Planes {
            height: vec![100; 0x10000],
            // The kraken (m6) is water-masked and now dies on land
            // (the :21225-91 mover rule) — the bare fixture is an
            // ocean so every model can live on it.
            tile_type: vec![0; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        let things = vec![Thing {
            slot: 0,
            kind: ThingKind::Entity,
            class: 5,
            model,
            x: 112,
            y: 110,
            dis_id: 0,
            swi_sz: 0,
            swi_id: 0,
            parent: 0,
            child: 0,
            par3: None,
        }];
        World::new(planes, &things, 7, assets())
    }

    // ---- mortality -------------------------------------------------------

    /// A landed pose: ground 100*32 = 3200, the touchdown floor is
    /// ground+128 = 3328 (firing_line's 3360 stays airborne).
    fn grounded_line() -> PlayerPose {
        PlayerPose::level((112 << 8) + 128, (116 << 8) + 128, 3328, 0)
    }

    fn hit_player(w: &mut World, amt: u32, src: u16) {
        w.g.mail_write(crate::mc1::combat::MailTarget::Player, 0, amt, src);
    }

    /// THE CLASS-12 CTOR STAMPS ITS WHOLE ROW (`sub_3BF70`
    /// :47979-48012, the one body every spell thunk shares): the burst
    /// count in `+50`, the price in `+136`, price/count in `+140` and
    /// BOTH life words zeroed over `NewEvent`'s 300. The port used to
    /// seed the mana pair for spell 16 alone, which mc1l42's respawn
    /// reads straight off — retail's re-minted fireball token is
    /// `max_life 0, +136 200, +140 40`.
    #[test]
    fn a_granted_manifestation_carries_its_whole_ctor_row() {
        let mut w = bare_creature_world(2);
        let m = w
            .grant_spell(crate::mc1::spells::SpellId(0))
            .expect("granted");
        let e = &w.g.ent[m];
        assert_eq!((e.class64, e.model65), (12, 0), "a fireball token");
        assert_eq!(e.f50, SPELLS[0].count as i16, "+50 = the burst count");
        assert_eq!(e.f136, SPELLS[0].possess_mana as i32, "+136 = the price");
        assert_eq!(e.f140, 40, "+140 = price/count, the HUD dot unit");
        assert_eq!((e.max_life, e.act_life), (0, 0), "both life words zeroed");
        assert_eq!(e.f44, SPELLS[0].damage as u16, "+44 = the row damage");

        // AND THE GAME'S OWN TABLE, NOT THE BASE CONST: HW forks
        // spell 20's whole ctor row (count 26, castle_req 60000,
        // damage 5000 — `sub_3C2B0` hw:44266), and the mint must read
        // it through `self.spells()`. mc1hwl0 t=7629: the respawn
        // re-mint took `f44` from the game table but +50/+136/+140
        // from the static base, building the (12,20) token at
        // `+50` 51 / `+140` 98 against retail's 26 / 192. No fixture
        // can pin the respawn face yet (a pair cannot anchor inside
        // the dead window — the importer holds no record for the
        // corpse), so the mint law is pinned here.
        let mut w = bare_creature_world(2);
        w.game = GameId::Mc1Hw;
        let m = w
            .grant_spell(crate::mc1::spells::SpellId(20))
            .expect("granted");
        let e = &w.g.ent[m];
        assert_eq!(
            (e.f50, e.f136, e.f140, e.f44),
            (26, 5000, 192, 5000),
            "the HW spell-20 row reaches the token lanes"
        );
    }

    /// THE CLAIM BOLT'S DEST IS THE CASTER PROJECTED 10240 ALONG THE
    /// LIVE AIM: `sub_56510` (:65247-49) copies the caster's own
    /// position into +150/+152/+154 and steps it 10240 through
    /// `sub_41EC0` on the caster's +30/+32 before copying the aim
    /// onto the bolt. mc1hwl0 t=7853 measures the whole projection
    /// to the unit: record (39016, 15164, 3238) + (yaw 178, pitch 72)
    /// → dest (44204, 6627, 995) — `SIN[72]·10240 = 2243` of drop.
    /// The dest lanes are conformance-dumped but not pair-graded and
    /// the cast-pose echo is import-reseeded, so no fixture can pin
    /// this; the free-run horizon and this unit are the guards.
    #[test]
    fn the_claim_bolt_carries_the_aim_projected_dest() {
        use crate::mc1::mobs::MobCtx;
        let mut w = bare_creature_world(2);
        let m = w
            .grant_spell(crate::mc1::spells::SpellId(3))
            .expect("granted");
        let pose = PlayerPose {
            x: 39016,
            y: 15164,
            z: 3238,
            heading: 178,
            pitch: 72,
            speed: 80,
        };
        let ctx = MobCtx {
            px: pose.x,
            py: pose.y,
            pz: pose.z,
            pyaw: pose.heading,
            pmana: 0,
            pmana_max: 0,
            pdead: false,
            pdead_top: false,
            strict: false,
            patches: crate::patches::WorldPatches::RETAIL,
            mc2_turn: 0,
        };
        w.emit_spell(3, m, pose, false, &ctx);
        let pr = (1..w.g.ent.len())
            .find(|&j| w.g.ent[j].class64 == 9 && w.g.ent[j].model65 == 1)
            .expect("the (9,1) claim bolt spawned");
        let e = &w.g.ent[pr];
        assert_eq!(
            (e.dest_x, e.dest_y, e.site_z),
            (44204, 6627, 995),
            "sub_56510's 10240 aim projection, mc1hwl0 t=7853 to the unit"
        );
    }

    /// `sub_37220_375E0` (:43825): the free/recycle REBUILD is a
    /// DESCENDING 999→1 scan, so the stack top — the next `new_event`
    /// — is the LOWEST inactive slot in the pool, not whatever the
    /// incremental stack last freed. Retail runs it at the death
    /// landing (:55487) and the respawn (:54842), which is why
    /// mc1l42's grave takes slot 109 and its re-minted spell tokens
    /// 110-117.
    #[test]
    fn the_free_list_rebuild_hands_out_the_lowest_slot() {
        let mut w = bare_creature_world(2);
        // Allocate a run, then free the LOW ones: the incremental
        // stack would hand back the last freed, retail's rebuild the
        // lowest-numbered.
        let mut got = Vec::new();
        for _ in 0..8 {
            let s = w.g.new_event().expect("pool has room");
            w.g.ent[s].class64 = 10;
            got.push(s);
        }
        got.sort_unstable();
        let (lo, hi) = (got[0], got[7]);
        w.g.free_entity(hi);
        w.g.free_entity(lo);
        let incremental = w.g.new_event().expect("pool has room");
        assert_eq!(incremental, lo, "the incremental stack pops the last freed");
        w.g.ent[incremental].class64 = 10;
        w.g.free_entity(incremental);

        w.g.mc1_rebuild_free(w.mc1_carpet_slot);
        let after = w.g.new_event().expect("pool has room");
        assert_eq!(after, lo.min(hi), "the rebuild pops the LOWEST free slot");
    }

    /// The (10,12) possession flash carries its ctor's `+44 = -1536`
    /// (`sub_3AA10` :46804) — a signed word in a u16 field, i.e.
    /// 64000, and what the recording reads on every flash in the
    /// corpus. Nothing consumes it (MC1's ch1 intake reads the SOURCE
    /// alone), so this is a field-value law; it is carried because the
    /// record carries it.
    #[test]
    fn the_possess_flash_carries_its_ctor_drain() {
        let mut w = bare_creature_world(2);
        let f =
            w.g.spawn_effect(12, 100 << 8, 100 << 8, 3200)
                .expect("spawned");
        assert_eq!(w.g.ent[f].f44, (-1536i16) as u16);
        assert_eq!(w.g.ent[f].max_life, 8);
    }

    /// THE PACK-DEATH HANDOFF WRITES THROUGH `+52` BLIND
    /// (`sub_1A390` :21695-21752). The only gate on the whole path is
    /// `+52 != 0` (:21695); the stamp then takes
    /// `v3x = &pool[a1x->+52]` (:21702) with no class, model, life or
    /// flags test and writes `+146`, `+52 = 0` and `+70 = a2 + 2` into
    /// whatever record occupies that slot NOW.
    ///
    /// The port carried an invented `class64 == 5` conjunct, and it
    /// cost mc1l2 its last graded row: at t=8290 the militiaman in
    /// slot 285 dies still pointing at slot 287, which had been reaped
    /// and re-minted as a `(10,0)` fire, and retail stamps the fire.
    /// A pair fixture pins the mc1l2 exemplar
    /// (`the-pack-death-handoff-writes-through-52-blind-s`); this is
    /// the unit guard, because the law's whole content is the ABSENCE
    /// of a test and nothing stops that test being re-added.
    #[test]
    fn the_pack_death_handoff_writes_through_f52_blind() {
        let mut w = bare_creature_world(4);
        // A militiaman (m4, family base 24) linked to a slot that is
        // NOT a creature — exactly mc1l2's reaped-and-re-minted fire.
        let mob =
            w.g.spawn_creature(4, 100 << 8, 100 << 8, 3200)
                .expect("spawned");
        let fire =
            w.g.spawn_effect(0, 100 << 8, 100 << 8, 3200)
                .expect("spawned");
        assert_eq!(w.g.ent[fire].class64, 10, "the partner is NOT class 5");
        w.g.ent[mob].tick70 = 24 + 3; // pack role
        w.g.ent[mob].f52 = fire as u16;
        w.g.ent[mob].f58 = 16; // awake, so the inbox runs
        // Kill it through the mailbox: the inbox's lethal branch is
        // what arms the handoff.
        w.g.ent[mob].mail[0] = (w.g.ent[mob].act_life as u32 + 1, 77);
        let ctx = MobCtx {
            px: 0x8000,
            py: 0x8000,
            pz: 3200,
            pyaw: 0,
            pmana: 0,
            pmana_max: 0,
            pdead: false,
            pdead_top: false,
            strict: false,
            patches: crate::patches::WorldPatches::RETAIL,
            mc2_turn: 0,
        };
        w.g.creature_tick(mob, &ctx);

        assert_eq!(
            w.g.ent[fire].f146, 77,
            "the dying pack member stamps its partner's chase with the killer, \
             whatever class the partner now is"
        );
        assert_eq!(w.g.ent[fire].f52, 0, "and clears the partner's own link");
        assert_eq!(
            w.g.ent[fire].tick70, 26,
            "and re-states it to a2 + 2 = 26 — which is why the ascending walk \
             then dispatches the fire as class-10 state 26"
        );
    }

    #[test]
    fn spawn_grace_absorbs_then_real_damage_knocks_and_kills() {
        let mut w = bare_creature_world(2);
        w.set_dev_spells(true); // all spells owned → a real jar scatter
        w.grant_all_spells();
        // Park the creature far away; it stays alive as the damage
        // SOURCE entity (the knockback bearing needs its position).
        w.g.move_relink(1, 30 << 8, 30 << 8, 3200);

        // 1) The grace window: hits are wiped, not totaled (:55367-71).
        for _ in 0..50 {
            hit_player(&mut w, 500, 1);
            w.tick(firing_line(), PlayerCommand::default());
        }
        assert_eq!(w.vitals().life, PLAYER_LIFE_MAX, "grace = total immunity");
        assert_eq!(w.player_damage_taken(), 0, "grace does not total");
        for _ in 0..50 {
            w.tick(firing_line(), PlayerCommand::default());
        }
        assert_eq!(w.vitals().grace, 0, "the 100-tick grace expired");

        // 2) A real hit: life drops, knockback arms (amt/10 clamp 80),
        // the red flash and the regen stall run.
        hit_player(&mut w, 500, 1);
        w.tick(firing_line(), PlayerCommand::default());
        assert_eq!(w.vitals().life, PLAYER_LIFE_MAX - 500);
        assert_eq!(w.knock_magnitude(), 50, "v_22 = amount/10");
        assert!(w.vitals().hit_flash > 0, "the red flash armed");

        // 3) Regen: /2000 afield = 5/tick once the 16-tick stall ends.
        for _ in 0..20 {
            w.tick(firing_line(), PlayerCommand::default());
        }
        let healed = w.vitals().life;
        assert!(healed > PLAYER_LIFE_MAX - 500, "afield regen ticked");
        assert!(healed < PLAYER_LIFE_MAX, "but nowhere near full yet");

        // 4) A lethal hit: the death fall begins.
        hit_player(&mut w, 30000, 1);
        w.tick(firing_line(), PlayerCommand::default());
        assert_eq!(w.vitals().state, LifeState::Falling);
        assert!(w.player_falling());

        // 5) Touchdown at ground+128: jars scatter, the grave rises,
        // the player-owned loose ball passes to the grave.
        let b =
            w.g.spawn_mana_ball((112 << 8) + 128, (114 << 8) + 128, 3200)
                .unwrap();
        w.g.ent[b].f144 = PLAYER_TARGET;
        w.tick(grounded_line(), PlayerCommand::default());
        assert_eq!(w.vitals().state, LifeState::Dead);
        assert_eq!(count(&w, 10, 40), 1, "the grave stands");
        let grave = w
            .debug_pool()
            .1
            .into_iter()
            .find(|e| e.class == 10 && e.model == 40)
            .unwrap()
            .slot as u16;
        assert_eq!(
            w.g.ent[b as usize].f144, grave,
            "the grave inherits the ball"
        );
        let jars = w
            .debug_pool()
            .1
            .iter()
            .filter(|e| e.class == 12 && e.state == 3)
            .count();
        assert!(jars > 0, "the spell inventory scattered as decaying jars");

        // 6) Castle-less respawn = the level is lost and restarts.
        w.tick(
            grounded_line(),
            PlayerCommand {
                respawn: true,
                ..Default::default()
            },
        );
        assert!(w.take_restart(), "castle-less death restarts the level");
        assert!(w.vitals().lost);
    }

