    #[test]
    fn death_with_a_castle_respawns_there_with_fresh_grace() {
        let mut w = bare_creature_world(2);
        w.set_dev_spells(true);
        w.grant_all_spells();
        w.g.move_relink(1, 30 << 8, 30 << 8, 3200);
        let c =
            w.g.spawn_castle((140 << 8) + 128, (140 << 8) + 128)
                .unwrap();
        w.g.ent[c].id24 = PLAYER_TARGET;
        w.g.ent[c].f144 = PLAYER_TARGET;
        for _ in 0..60 {
            w.tick(firing_line(), PlayerCommand::default());
        }
        assert!(w.loadout().castle.is_some(), "castle established");

        w.player.grace = 0;
        hit_player(&mut w, 30000, 1);
        w.tick(firing_line(), PlayerCommand::default());
        w.tick(grounded_line(), PlayerCommand::default());
        assert_eq!(w.vitals().state, LifeState::Dead);
        let owned_before = w.loadout().owned.iter().filter(|&&o| o).count();
        assert_eq!(
            owned_before, 0,
            "ownership rides the death slots while dead"
        );

        w.tick(
            grounded_line(),
            PlayerCommand {
                respawn: true,
                ..Default::default()
            },
        );
        let (rx, rz, _ralt) = w.take_respawn().expect("respawn fired");
        // The castle grid-snaps to even tile parity; just confirm the
        // destination is the castle's tile neighborhood.
        assert!((rx - 140.0).abs() < 2.0 && (rz - 140.0).abs() < 2.0);
        assert_eq!(w.vitals().state, LifeState::Alive);
        assert_eq!(w.vitals().life, PLAYER_LIFE_MAX);
        assert_eq!(w.vitals().grace, 100, "fresh spawn grace");
        assert!(!w.take_restart(), "no restart with a castle standing");
        let owned_after = w.loadout().owned.iter().filter(|&&o| o).count();
        assert!(owned_after >= 24, "the spell inventory re-instantiated");
    }

    /// THE LANDING ENDS THE TIMED EFFECTS (player report 2026-09-09:
    /// a wizard killed under Accelerate kept its x3 override through
    /// the dead wait and past the respawn). Retail's scatter zeroes
    /// every token's burst counter so no effect body runs again; the
    /// port's player-side latches must die at the same moment — see
    /// [`World::player_death_clear_effects`]. The record-borne bits
    /// (shield/invisible/rebound) are NOT in scope here.
    #[test]
    fn the_death_landing_ends_accelerate_heal_and_beyond_sight() {
        let mut w = bare_creature_world(2);
        w.set_dev_spells(true);
        w.grant_all_spells();
        w.g.move_relink(1, 30 << 8, 30 << 8, 3200);
        let c =
            w.g.spawn_castle((140 << 8) + 128, (140 << 8) + 128)
                .unwrap();
        w.g.ent[c].id24 = PLAYER_TARGET;
        w.g.ent[c].f144 = PLAYER_TARGET;
        for _ in 0..60 {
            w.tick(firing_line(), PlayerCommand::default());
        }
        // The player's own configuration: the book is permanent, so
        // the tokens stay live through the death and the landing has
        // to end their bursts itself.
        w.set_patches(crate::patches::WorldPatches {
            no_spell_loss: true,
            ..crate::patches::WorldPatches::RETAIL
        });
        // A live Accelerate window (held, 200 ticks left), Heal and
        // Beyond Sight.
        let tok = w.player.owned[2] as usize;
        assert!(tok != 0, "dev spells own an Accelerate token");
        w.g.ent[tok].f26 = 200;
        w.g.ent[tok].flags |= 0x80;
        w.player.accel = 1;
        w.player.accel_held = true;
        w.player.speed_boost = 3.0;
        w.player.heal_active = true;
        w.player.beyond_sight = true;
        w.player.shield = true; // record-borne: must survive untouched
        assert_eq!(w.accel_override(), Some(3.0));

        w.player.grace = 0;
        // 60000: the standing shield bit quarters ONE hit (15000 >
        // the 10000 life ceiling still kills).
        hit_player(&mut w, 60000, 1);
        w.tick(firing_line(), PlayerCommand::default());
        assert_eq!(w.vitals().state, LifeState::Falling);
        // The FALL keeps the override: retail's state-2 dispatch
        // still moves the carpet on its frozen boosted columns.
        assert!(w.accel_override().is_some(), "the fall glides on the boost");

        w.tick(grounded_line(), PlayerCommand::default());
        assert_eq!(w.vitals().state, LifeState::Dead);
        assert_eq!(w.accel_override(), None, "touchdown ends the override");
        assert_eq!(w.player.accel, 0);
        assert_eq!(w.player.accel_mc2_factor, 0);
        assert!(!w.player.heal_active, "heal latch dropped");
        assert!(!w.player.beyond_sight, "beyond-sight latch dropped");
        assert!(
            !w.player.shield,
            "the standing bit was spent by the absorb, not by this law"
        );
        assert_eq!(w.g.ent[tok].f26, 0, "the kept token's burst is over");
        assert_eq!(w.g.ent[tok].flags & 0x80, 0, "…and its ACTIVE bit down");
        let _ = w.take_speed_base();

        // Nothing re-arms across the dead wait or the respawn.
        for _ in 0..5 {
            w.tick(grounded_line(), PlayerCommand::default());
            assert_eq!(w.accel_override(), None, "no override on the corpse");
        }
        w.tick(
            grounded_line(),
            PlayerCommand {
                respawn: true,
                ..Default::default()
            },
        );
        assert_eq!(w.vitals().state, LifeState::Alive);
        assert_eq!(w.accel_override(), None, "the respawn flies unboosted");
        let _ = w.take_speed_base();
        for _ in 0..3 {
            w.tick(firing_line(), PlayerCommand::default());
            assert_eq!(w.accel_override(), None, "…and stays so");
            assert_eq!(w.take_speed_base(), None, "no speed mail from a dead burst");
        }
    }

    /// The intermittent hand-spell eater (player report mc1:49 +
    /// mc1hw:0): respawning on an exhausted pool must not turn a
    /// failed re-instantiation into a permanent loss — the death bank
    /// keeps remembering the model until a manifestation slot exists.
    #[test]
    fn respawn_on_an_exhausted_pool_never_eats_the_inventory() {
        let mut w = bare_creature_world(2);
        w.set_dev_spells(true);
        w.grant_all_spells();
        w.g.move_relink(1, 30 << 8, 30 << 8, 3200);
        let c =
            w.g.spawn_castle((140 << 8) + 128, (140 << 8) + 128)
                .unwrap();
        w.g.ent[c].id24 = PLAYER_TARGET;
        w.g.ent[c].f144 = PLAYER_TARGET;
        for _ in 0..60 {
            w.tick(firing_line(), PlayerCommand::default());
        }

        w.player.grace = 0;
        hit_player(&mut w, 30000, 1);
        w.tick(firing_line(), PlayerCommand::default());
        w.tick(grounded_line(), PlayerCommand::default());
        assert_eq!(w.vitals().state, LifeState::Dead);

        // The endgame crowd: every free slot is taken the moment the
        // player presses Space (the scattered jars still hold their
        // own slots, so the re-grant loop starves).
        let mut hogs = Vec::new();
        while let Some(h) = w.g.new_event() {
            // Stamp a class on every hog: `NewEvent` hands out a
            // ZEROED record and each real ctor classes it at once, so
            // an unclassed slot is a state retail cannot be in — and
            // the respawn's own free-list rebuild (`sub_37220`, which
            // reads `+64 == 0` as FREE) would hand every one of them
            // straight back and the starve under test would never
            // happen.
            w.g.ent[h].class64 = 10;
            hogs.push(h);
        }
        // Respawn AT THE CASTLE, far from the corpse — the scattered
        // jars are out of pickup range and will decay unseen (the
        // report's "no jars left behind either").
        let castle_air = PlayerPose::level((140 << 8) + 128, (140 << 8) + 128, 3360, 0);
        w.tick(
            castle_air,
            PlayerCommand {
                respawn: true,
                ..Default::default()
            },
        );
        assert_eq!(w.vitals().state, LifeState::Alive);
        let held = w.loadout().owned.iter().filter(|&&o| o).count();
        assert!(held < 24, "the starved grants really did fail");

        // The crowd thins and every scattered jar runs out its
        // 200-289-tick fuse; the remembered models must still return.
        for &h in &hogs {
            w.g.free_entity(h);
        }
        for _ in 0..320 {
            w.tick(castle_air, PlayerCommand::default());
        }
        let recovered = w.loadout().owned.iter().filter(|&&o| o).count();
        assert!(
            recovered >= 24,
            "the pool freed but only {recovered}/24 spells came back — \
             the respawn grant failure ate the rest"
        );
    }

    /// mc1hwl0 t=7592→7628 (dump-state ground truth): the death
    /// scatter is retail's BLIND in-place walk of all 24 list entries
    /// (:55517-24) — every live entry becomes the pointed-at record's
    /// MODEL byte, every empty becomes −1, and ORDER is preserved.
    /// Retail's own list read [17,57,94,109,28,108,107,161,162] before
    /// the landing and [0,3,16,2,20,23,4,7,10,−1×15] after it; the
    /// old guarded loop skipped entries that failed its invented
    /// ownership test (leaving them in SLOT form — session 48's
    /// stale-17 alias) and left empties at 0, which the dead form
    /// cannot mean (0 = fireball there).
    #[test]
    fn the_death_scatter_banks_models_in_place_and_stamps_minus_one_empties() {
        let mut w = flat_world();
        w.grant_spells(&[0, 3, 16, 2]);
        let expect: Vec<i32> = w.mc1_acq[..4]
            .iter()
            .map(|&e| w.g.ent[e as usize].model65 as i32)
            .collect();
        assert_eq!(expect, vec![0, 3, 16, 2], "grant order IS list order");
        w.player.grace = 0;
        hit_player(&mut w, 30000, 1);
        w.tick(firing_line(), PlayerCommand::default());
        w.tick(grounded_line(), PlayerCommand::default());
        assert_eq!(w.vitals().state, LifeState::Dead);
        assert_eq!(
            &w.mc1_acq[..4],
            &[0, 3, 16, 2],
            "live entries bank the MODEL at their own index — 0 is \
             fireball's, not an empty"
        );
        assert!(
            w.mc1_acq[4..].iter().all(|&e| e == -1),
            "every empty entry is stamped the dead-form −1 sentinel \
             (got {:?})",
            &w.mc1_acq[4..]
        );
    }

    /// mc1hwl0 t=7629→7630: the STRICT respawn regrant is retail's
    /// one-shot in-place walk (:54893-917). Each banked model mints
    /// over ITS OWN entry; −1 goes back to 0; a starved mint ZEROES
    /// the entry — the permanent silent loss (:54917, the l49 "lost
    /// wall of fire"). Session 48's find-based restore collided three
    /// ways on this exact take (s=0 matched the first free entry,
    /// banked models 20 and 23 matched freshly-written slots 20 and
    /// 23) and `grant_spell`'s push appended a duplicate per mint —
    /// one respawn left 17 entries where retail leaves 9.
    #[test]
    fn the_strict_respawn_regrant_is_in_place_one_shot_with_silent_loss() {
        let mut w = flat_world();
        w.strict_retail = true;
        // The mc1hwl0 dead-form list, verbatim.
        let bank = [0i32, 3, 16, 2, 20, 23, 4, 7, 10];
        w.mc1_acq = [-1; SPELL_COUNT];
        for (i, &m) in bank.iter().enumerate() {
            w.mc1_acq[i] = m;
            w.player.death_owned[m as usize] = true;
        }
        w.player.owned = [0; SPELL_COUNT];
        w.death_regrant(Some((140 << 8, 140 << 8, 3200)));
        for (i, &m) in bank.iter().enumerate() {
            let e = w.mc1_acq[i];
            assert!(e > 0, "entry {i} re-minted in place (got {e})");
            assert_eq!(
                w.g.ent[e as usize].model65 as i32, m,
                "entry {i} holds the slot of ITS OWN model {m}, not a \
                 find-collision neighbour's"
            );
            assert_eq!(
                w.g.ent[e as usize].tick70,
                3 * m as u8,
                "strict re-mint lands on retail phase 0 (spell*3)"
            );
        }
        assert!(
            w.mc1_acq[bank.len()..].iter().all(|&e| e == 0),
            "−1 empties go back to alive-form 0 and NOTHING is \
             appended behind them (the push-per-mint duplicate storm): {:?}",
            &w.mc1_acq[bank.len()..]
        );
        let listed: Vec<i32> = w.mc1_acq.iter().copied().filter(|&e| e > 0).collect();
        let mut dedup = listed.clone();
        dedup.sort_unstable();
        dedup.dedup();
        assert_eq!(
            listed.len(),
            dedup.len(),
            "no duplicate entries: {listed:?}"
        );

        // The starve arm: a full pool at respawn is retail's own
        // permanent loss under strict — the entry zeroes and the
        // spell does NOT come back when the pool frees (the native
        // retry deviation stays native-only).
        let mut s = flat_world();
        s.strict_retail = true;
        s.mc1_acq = [-1; SPELL_COUNT];
        s.mc1_acq[0] = 20;
        s.player.death_owned[20] = true;
        s.player.owned = [0; SPELL_COUNT];
        let mut hogs = Vec::new();
        while let Some(h) = s.g.new_event() {
            s.g.ent[h].class64 = 10;
            hogs.push(h);
        }
        s.death_regrant(Some((140 << 8, 140 << 8, 3200)));
        assert_eq!(s.mc1_acq[0], 0, ":54917 — the starved entry zeroes");
        assert!(
            !s.player.death_owned[20],
            "strict keeps no retry bank — the spell is silently lost"
        );
        for &h in &hogs {
            s.g.free_entity(h);
        }
        for _ in 0..4 {
            s.tick(firing_line(), PlayerCommand::default());
        }
        assert_eq!(
            s.player.owned[20], 0,
            "the pool freed and the spell must STAY lost under strict \
             (the alive-retry is the native-only deviation)"
        );
    }

    #[test]
    fn mc2_grounded_hive_still_takes_damage() {
        // sub_20940 (EF:12357-75) runs the damage/death head FIRST.
        // Ours returned before it, so a hive that had settled into its
        // feeding squat was UNKILLABLE — the arm this pins.
        let mut w = mc2_flat_world();
        let h = w.g.mc2_spawn_m9(112 << 8, 110 << 8, 3200).expect("hive");
        // Keep the player far so the hive falls asleep and grounds.
        let far = PlayerPose::level(10 << 8, 10 << 8, 3400, 0);
        let mut grounded = false;
        for _ in 0..4000 {
            w.tick(far, PlayerCommand::default());
            if w.g.ent[h].f71 != 0 {
                grounded = true;
                break;
            }
        }
        assert!(
            grounded,
            "an undisturbed hive settles into the grounded squat"
        );
        let before = w.g.ent[h].act_life;
        assert!(before > 0);
        w.g.ent[h].mail[0] = (before as u32 + 1, PLAYER_TARGET);
        w.tick(far, PlayerCommand::default());
        assert!(
            w.g.ent[h].act_life < before,
            "a GROUNDED hive takes the damage in its inbox (it was immune)"
        );
    }

    #[test]
    fn castle_transformation_kills_the_footprint_but_spares_the_exempt() {
        let mut w = bare_creature_world(2); // wild lunger at ~(113,110)
        // An owned creature and a boss-exempt m16 on the footprint.
        let owned = w.g.spawn_creature(2, 112 << 8, 110 << 8, 3200).unwrap();
        w.g.ent[owned].id24 = PLAYER_TARGET;
        let boss = w.g.spawn_creature(16, 111 << 8, 110 << 8, 3200).unwrap();
        let wild_life = w.g.ent[1].act_life;
        assert!(wild_life > 0);

        // The castle rises straight under them (the level-0 build
        // skips the space gate — the initial cast is single-step).
        let c = w.g.spawn_castle(112 << 8, 110 << 8).unwrap();
        w.g.ent[c].id24 = PLAYER_TARGET;
        w.g.ent[c].f144 = PLAYER_TARGET;
        for _ in 0..40 {
            w.tick(
                PlayerPose::level(90 << 8, 90 << 8, 3400, 0),
                PlayerCommand::default(),
            );
        }
        assert_eq!(count(&w, 5, 2), 1, "exactly one m2 survives...");
        assert_eq!(w.g.ent[owned].id24, PLAYER_TARGET);
        assert!(
            w.g.ent[owned].act_life > 0,
            "...the OWNED one (owner immunity)"
        );
        assert!(
            w.g.ent[boss].act_life > 0,
            "m16 is exempt from the execution"
        );
        let (kills, _, _) = w.combat_stats();
        assert_eq!(kills, 1, "the execution credits the castle owner");
    }

    /// ⭐⭐⭐ THE ACTION-6 CREATE-CASTLE TOKEN PIN LIVES INSIDE THE
    /// LEVELER'S POOL GUARD. `sub_470E0` (:56142-56) is
    ///
    /// ```text
    ///   result = sub_37710_37AD0();          // free-stack depth
    ///   if (result) { sub_47A70_47DB0(a1); a1+70 = 4; … }
    ///   else        { a1+70 = 4; }
    /// ```
    ///
    /// and the token pin/release pair is inside `sub_47A70_47DB0`
    /// (:56529 `sub_46D20_47060(a1, 1)` under `if (+26 > 0)`, :56533
    /// `…(a1, 0)` under `if (+26 == 0)`) — NOT in `sub_470E0`'s own
    /// body. So an action-6 pass on an EXHAUSTED pool parks `+70` back
    /// to 4 and leaves the owner's Create-Castle token's `+48` exactly
    /// where it stood. The port already gated the DOWNGRADE
    /// ([`Gen::castle_tick`], `MGC_NO_MC1_LEVELER_POOL_GATE`) but
    /// stamped the token outside the guard, so a besieged castle in a
    /// starved world re-armed its owner's token to `+50 − 1` = 100 on
    /// every other tick.
    ///
    /// ⚠ NO FIXTURE CAN PIN THIS. `+48` is not a field of `EntObsMc1`
    /// (`mgc-formats/src/mgcr.rs`) — the recorder never projects it —
    /// and its only graded consequence is downstream, through
    /// `sub_14120`'s `token+48 == 0` term, as a `chase` (`+146`)
    /// divergence that classifies INHERITED. mc1l49 measures it:
    /// rival 672's castle 953 is fatally hit at t=17809 and oscillates
    /// `+70` 4→6→4 through t=17813 while retail's own free stack reads
    /// EMPTY (`var_u32_40 = −1`) at every snapshot from 17805 to
    /// 17815; retail holds token 676's `+48 = 0` across that whole
    /// window AND leaves the castle's rung at 2, then pins at t=17814,
    /// the tick whose reap leaves the leveler a record to spend and
    /// the rung drops 2 → 1. The ungated port pinned at t=17810,
    /// shutting the Upgrade arm on ticks 17811/17813/17870 (`+146` 953
    /// vs the port's 569 — three segment heads, all pair-clean).
    /// This test is the pin. Kill switch `MGC_NO_MC1_LEVELER_PIN_GATE`.
    #[test]
    fn a_starved_leveler_leaves_the_castle_token_alone() {
        let pose = PlayerPose::level(90 << 8, 90 << 8, 3400, 0);
        // Arm: a level-2 castle owned by the human, with the human's
        // own Create-Castle manifestation as the pin target.
        let build = |free_stack: bool| -> (World, usize, usize) {
            let mut w = bare_creature_world(2);
            w.g.move_relink(1, 30 << 8, 30 << 8, 3200);
            w.grant_spells(&[16]);
            let c = w.g.spawn_castle(140 << 8, 140 << 8).unwrap();
            w.g.ent[c].id24 = PLAYER_TARGET;
            w.g.ent[c].f144 = PLAYER_TARGET;
            for _ in 0..60 {
                w.tick(pose, PlayerCommand::default());
            }
            w.g.ent[c].mail[5] = (10, PLAYER_TARGET);
            for _ in 0..60 {
                w.tick(pose, PlayerCommand::default());
            }
            assert_eq!(
                w.loadout().castle.map(|(_, _, l)| l),
                Some(2),
                "the castle stands at level 2"
            );
            let m = w
                .castle_owner_token(PLAYER_TARGET)
                .expect("the human holds a (12,16) token");
            // Park the token IDLE — retail's state through the whole
            // mc1l49 t=17808..17813 window.
            w.g.ent[m].f26 = 0;
            // The lethal tick only PARKS the castle in action 6
            // (:56003); the leveler runs at the top of the NEXT tick.
            w.g.ent[c].f140 = 30_000;
            w.g.mail_write(crate::mc1::combat::MailTarget::Pool(c), 0, 45_000, 1);
            w.tick(pose, PlayerCommand::default());
            assert_eq!(w.g.ent[c].tick70, 6, "parked in the leveler");
            assert_eq!(w.g.ent[m].f26, 0, "the parking tick pins nothing");
            if !free_stack {
                w.g.free.clear();
            }
            (w, c, m)
        };

        // A — the starved pool. `sub_37710_37AD0()` reads 0, so
        // `sub_47A70_47DB0` never runs: no rung decrement AND no pin.
        let (mut w, c, m) = build(false);
        w.tick(pose, PlayerCommand::default());
        assert_eq!(
            w.g.ent[c].tick70, 4,
            "the starved leveler still parks +70 back to 4"
        );
        assert_eq!(
            w.loadout().castle.map(|(_, _, l)| l),
            Some(2),
            "…and runs no teardown (the rung is untouched)"
        );
        assert_eq!(
            w.g.ent[m].f26, 0,
            "…so the owner's Create-Castle token keeps its +48: the \
             pin lives INSIDE sub_47A70_47DB0's guard (:56529)"
        );

        // B — the same tick with a record to spare: the teardown runs
        // and the pin lands, `+48 = +50 − 1`.
        let (mut w, c, m) = build(true);
        w.tick(pose, PlayerCommand::default());
        assert_eq!(
            w.loadout().castle.map(|(_, _, l)| l),
            Some(1),
            "a fed leveler takes the rung"
        );
        assert_eq!(
            w.g.ent[m].f26,
            SPELLS[16].count as i16 - 1,
            "…and pins the token on its way (:56529)"
        );
        assert_eq!(w.g.ent[c].tick70, 4);
    }

    #[test]
    fn castle_downgrade_ejects_mana_and_demolish_razes() {
        let mut w = bare_creature_world(2);
        reseat_carpet_above(&mut w);
        w.g.move_relink(1, 30 << 8, 30 << 8, 3200);
        let pose = PlayerPose::level(90 << 8, 90 << 8, 3400, 0);
        let c = w.g.spawn_castle(140 << 8, 140 << 8).unwrap();
        w.g.ent[c].id24 = PLAYER_TARGET;
        w.g.ent[c].f144 = PLAYER_TARGET;
        for _ in 0..60 {
            w.tick(pose, PlayerCommand::default());
        }
        // Promote to level 2 through the authentic ch5 upgrade mail.
        w.g.ent[c].mail[5] = (10, PLAYER_TARGET);
        for _ in 0..60 {
            w.tick(pose, PlayerCommand::default());
        }
        let (_, cap, lvl) = w.loadout().castle.expect("castle stands");
        assert_eq!((lvl, cap), (2, 20_000));

        // Bank mana, then overkill it: one level down, the overkill
        // carries (capped at half), the spill flies out as balls.
        w.g.ent[c].f140 = 30_000;
        w.g.mail_write(crate::mc1::combat::MailTarget::Pool(c), 0, 45_000, 1);
        // The lethal tick only PARKS the castle in action 6 (:56003);
        // it holds its negative life for this whole tick and the
        // leveler runs at the top of the next (sub_470E0 :56138).
        // Retail is directly observable here — mc1l5 slot 312 sits at
        // act_life = -350 for exactly one tick before the ladder reset.
        w.tick(pose, PlayerCommand::default());
        assert_eq!(
            (w.g.ent[c].tick70, w.g.ent[c].act_life),
            (6, -5_000),
            "one tick parked at the overkill, not yet downgraded"
        );
        assert_eq!(
            w.loadout().castle.map(|(_, _, l)| l),
            Some(2),
            "the level does not drop until the leveler runs"
        );
        w.tick(pose, PlayerCommand::default());
        let (_, cap, lvl) = w.loadout().castle.expect("downgraded, not dead");
        assert_eq!((lvl, cap), (1, 10_000), "one level per lethal event");
        assert_eq!(
            w.g.ent[c].act_life, 15_000,
            "20000 max minus the 5000 overkill carry"
        );
        assert!(count(&w, 10, 39) >= 2, "the spill scattered as mana balls");
        // THREE ejector passes on this over-banked downgrade (retail
        // law): the death-NOTICE tick still runs the established
        // f63-even block (sub_46DB0 :56003 falls through), whose
        // ejector clamps the synthetic 30000 bank to the old cap;
        // then sub_47A70's haircut pass (spill above 90% of the OLD
        // cap) and the state-6 wrapper's pass at the NEW cap
        // (sub_470E0 :56147) — 10000, 2000 and 8000 here, each
        // spilling pass with its own 4 magnets, and the bank parks
        // exactly at the new cap.
        assert_eq!(count(&w, 10, 54), 12, "all three ejector passes' magnets");
        assert_eq!(
            w.g.ent[c].f140, 10_000,
            "the wrapper pass drains the bank to the new cap"
        );

        // Let the repaint cycle finish, then demolish: level 1 → 0
        // = total destruction, castle-less.
        for _ in 0..80 {
            w.tick(pose, PlayerCommand::default());
        }
        w.tick(
            pose,
            PlayerCommand {
                demolish: true,
                ..Default::default()
            },
        );
        for _ in 0..4 {
            w.tick(pose, PlayerCommand::default());
        }
        assert!(w.loadout().castle.is_none(), "the demolish razed it");
        assert_eq!(count(&w, 3, 2), 0, "the entity is gone");
    }

    /// The total-death scatter, arithmetic-exact (RETAIL LAW via the
    /// state-6 wrapper, sub_470E0 :56147-50 — corrected 2026-08-12;
    /// docs/DEVIATIONS.md "total-death scatter + fleet demolition").
    /// Corpus pin: mc1l0 t=2217, castle slot 107 dies holding 8302 —
    /// 8 balls of 8302/8 = 1037 (count = spill/1000), residual
    /// 8302 % 8 = 6 stays on the freed record, the flag re-caps to
    /// CAP[0] = 5000 with NO life re-stamp (sub_47BD0 row 0 carries
    /// hp 0), the ejector's 4 magnets spawn, and the level-0 fleet
    /// quota culls the balloon.
    #[test]
    fn castle_death_scatters_the_whole_bank_arithmetic_exact() {
        let mut w = bare_creature_world(2);
        reseat_carpet_above(&mut w);
        w.g.move_relink(1, 30 << 8, 30 << 8, 3200);
        let pose = PlayerPose::level(90 << 8, 90 << 8, 3400, 0);
        let c = w.g.spawn_castle(140 << 8, 140 << 8).unwrap();
        w.g.ent[c].id24 = PLAYER_TARGET;
        w.g.ent[c].f144 = PLAYER_TARGET;
        for _ in 0..80 {
            w.tick(pose, PlayerCommand::default());
        }
        assert_eq!(count(&w, 3, 3), 1, "the level-1 fleet balloon stands");
        w.g.ent[c].f140 = 8302;
        // The demolish write lands after the entity pass, so the
        // castle sees its −1 on the NEXT dispatch and parks in
        // action 6 for one tick…
        w.tick(
            pose,
            PlayerCommand {
                demolish: true,
                ..Default::default()
            },
        );
        w.tick(pose, PlayerCommand::default());
        assert_eq!(w.g.ent[c].tick70, 6, "parked, not yet torn down");
        // …and the teardown runs on the next dispatch. The record is
        // soft-killed but still readable this tick (the reap collects
        // it at the NEXT tick top) — exactly the frame the corpus
        // observes.
        w.tick(pose, PlayerCommand::default());
        assert!(w.g.ent[c].flags & 0x400 != 0, "soft-killed");
        assert_eq!(w.g.ent[c].f140, 6, "residual = 8302 % 8");
        assert_eq!(w.g.ent[c].f136, 5000, "the CAP[0] re-stamp");
        assert!(w.g.ent[c].act_life < 0, "row 0 hp = 0: no life re-stamp");
        let balls: Vec<usize> = (1..w.g.ent.len())
            .filter(|&j| {
                let e = &w.g.ent[j];
                e.class64 == 10 && e.model65 == 39 && e.flags & 0x400 == 0
            })
            .collect();
        assert_eq!(balls.len(), 8, "count = spill/1000");
        for &b in &balls {
            let e = &w.g.ent[b];
            assert_eq!(e.f140, 1037, "share = 8302/8");
            assert_eq!(e.f144, PLAYER_TARGET, "owner-tagged");
            assert_eq!((e.f66, e.f67), (10, 39), "the ctor source stamp");
            assert!((16..64).contains(&e.f126), "the ejector speed draw");
        }
        assert_eq!(count(&w, 10, 54), 4, "the ejector's four magnets");
        // The culled balloon carries 0x400 for one more snapshot (the
        // reap collects it next tick-top) — the corpus's flags-1036
        // frame exactly.
        let culled = (1..w.g.ent.len()).filter(|&j| {
            let e = &w.g.ent[j];
            e.class64 == 3 && e.model65 == 3 && e.flags & 0x400 != 0
        });
        assert_eq!(culled.count(), 1, "the level-0 quota culled the fleet");
    }

    /// Mana Magnet (spell 19), the full retail chain: the c9 m17
    /// bolt (possession's flight, :66078) detonates ON a struck ball
    /// into the invisible (10,54) magnet (:66084-85) PLUS the
    /// localized claim of the struck ball only; the magnet's ch4
    /// mail PULLS the distant ball WITHOUT claiming it; the claim
    /// arrives when the pulled ball MERGES into the claimed one
    /// (sub_277D0 :29717, owned-beats-unowned adoption). Also guards
    /// the old placeholder's regression: no (10,40) grave-model
    /// event at the impact (it drew as a humanoid).
    #[test]
    fn mana_magnet_claims_struck_ball_then_the_rest_by_merge() {
        let mut w = bare_creature_world(2);
        w.g.move_relink(1, 30 << 8, 30 << 8, 3200);
        let pose = PlayerPose::level(90 << 8, 90 << 8, 3400, 0);
        // The DISTANT ball first (lower slot: it will be the merge
        // survivor, exercising the adoption arm), 6 tiles east.
        // (f46 zeroed: settled balls, not the spawn-pop — a cast at
        // loose ground mana is the scenario.)
        let far = w.g.spawn_mana_ball(146 << 8, 140 << 8, 3200).unwrap();
        w.g.ent[far].f140 = 500;
        w.g.ent[far].f46 = 0;
        // The struck ball at the impact point.
        let near = w.g.spawn_mana_ball(140 << 8, 140 << 8, 3200).unwrap();
        w.g.ent[near].f140 = 300;
        w.g.ent[near].f46 = 0;
        // The bolt, parked on the struck ball (speed zeroed so the
        // first flight tick's ball scan lands the hit in place).
        let p = w.g.spawn_spell_lob(17, 140 << 8, 140 << 8, 3200).unwrap();
        w.g.ent[p].id24 = PLAYER_TARGET;
        w.g.ent[p].f126 = 0;
        w.g.ent[p].f69 = 54; // the cast arm's +69 (:66084-85)
        w.tick(pose, PlayerCommand::default());
        assert_eq!(count(&w, 10, 54), 1, "the impact spawned THE magnet");
        assert_eq!(count(&w, 10, 12), 1, "...plus the localized claim flash");
        assert_eq!(count(&w, 10, 40), 0, "and no grave-model placeholder");
        let dist = |w: &World| {
            let e = &w.g.ent[far];
            crate::engine::features::Gen::dist2_sq(e.x, e.y, 140 << 8, 140 << 8)
        };
        let d0 = dist(&w);
        for _ in 0..10 {
            w.tick(pose, PlayerCommand::default());
        }
        assert_eq!(
            w.g.ent[near].f144, PLAYER_TARGET,
            "the STRUCK ball is claimed at impact"
        );
        assert_eq!(
            w.g.ent[far].f144, 0,
            "the pulled ball is NOT claimed by the pull"
        );
        assert!(
            dist(&w) < d0,
            "...but it is streaming toward the magnet ({} -> {})",
            d0,
            dist(&w)
        );
        for _ in 0..110 {
            w.tick(pose, PlayerCommand::default());
        }
        assert_eq!(count(&w, 10, 39), 1, "the balls merged");
        assert_eq!(
            w.g.ent[far].f144, PLAYER_TARGET,
            "the unowned survivor ADOPTED the claimed ball's owner"
        );
        assert_eq!(w.g.ent[far].f140, 800, "merge mana is additive");
    }

