    /// The magnet bolt claims a dwelling it PASSES THROUGH in flight
    /// (player retail-verified) — not only when the detonation flash
    /// lands at the flag. The bolt here expires ~25 tiles past the
    /// house, so only the in-flight touch (the reconstruction
    /// bridge, proj_m1_tick) can be the claimer.
    #[test]
    fn mana_magnet_pass_through_claims_a_dwelling() {
        let mut w = bare_creature_world(2);
        w.g.move_relink(1, 30 << 8, 30 << 8, 3200);
        let pose = PlayerPose::level(90 << 8, 90 << 8, 3400, 0);
        // A live neutral dwelling with its footprint extents.
        let h = w.g.new_event().unwrap();
        {
            let e = &mut w.g.ent[h];
            e.class64 = 10;
            e.model65 = 45;
            e.tick70 = 52;
            e.flags |= 8 | 1;
            e.f28 = 35; // ch0 + ch1 (built-house contract) + bit 5
            e.f44 = 2000;
            e.act_life = 2000;
            e.f80 = 832;
            e.f82 = 832;
            e.f84 = 0x4000;
        }
        w.g.link(h, 143 << 8, 140 << 8, 3200);
        // The magnet bolt flying due east THROUGH the house, nothing
        // beyond it: it expires far past (the flash box cannot reach
        // back).
        let p = w.g.spawn_spell_lob(17, 140 << 8, 140 << 8, 3300).unwrap();
        w.g.ent[p].id24 = PLAYER_TARGET;
        w.g.ent[p].f69 = 54;
        w.g.ent[p].f30 = 512;
        w.g.ent[p].f34 = 512;
        for _ in 0..30 {
            w.tick(pose, PlayerCommand::default());
        }
        assert_eq!(count(&w, 9, 17), 0, "the bolt flew through and expired");
        assert_eq!(
            w.g.ent[h].f144, PLAYER_TARGET,
            "the pass-through claimed the dwelling"
        );
    }

    /// The magnet bolt's strike scan is MANA BALLS ONLY (sub_11C00)
    /// — a grave under the bolt is not a strike: the bolt flies on
    /// and detonates on its own expiry. The landing (10,12) flash
    /// then area-claims by the +28 bit-1 mask like any possession
    /// flash — a grave inside the box IS claimed (the caster
    /// inherits its holdings and the grave vanishes, grave_tick).
    #[test]
    fn mana_magnet_bolt_ignores_graves_in_flight_but_the_flash_claims() {
        let mut w = bare_creature_world(2);
        w.g.move_relink(1, 30 << 8, 30 << 8, 3200);
        let pose = PlayerPose::level(90 << 8, 90 << 8, 3400, 0);
        let g = w.g.spawn_grave(140 << 8, 140 << 8, 3200).unwrap();
        let _ = g;
        let p = w.g.spawn_spell_lob(17, 140 << 8, 140 << 8, 3200).unwrap();
        w.g.ent[p].id24 = PLAYER_TARGET;
        w.g.ent[p].f126 = 0; // parked ON the grave
        w.g.ent[p].f69 = 54;
        w.tick(pose, PlayerCommand::default());
        assert_eq!(
            count(&w, 10, 40),
            1,
            "no strike: the grave is not a collision victim"
        );
        for _ in 0..25 {
            w.tick(pose, PlayerCommand::default());
        }
        assert_eq!(count(&w, 10, 54), 1, "expiry drops the magnet in place");
        assert_eq!(
            count(&w, 10, 40),
            0,
            "the landing flash possessed the grave (bit-1 mask)"
        );
    }

    /// Total castle destruction DEMOLISHES the fleet through the
    /// cull's spill: each owned balloon dies and its cargo drops as
    /// an owned (10,39) ball, so the census total is conserved.
    /// RETAIL LAW, not a patch (corrected 2026-08-12): the state-6
    /// wrapper (sub_470E0 :56147-50) runs sub_47400 AFTER the
    /// teardown, and the level-0 quota culls every balloon with the
    /// cargo drop (:56399-411) — the mc1l0 corpus pins it (t=1363/
    /// 2217 balloon flags 1036 on the death tick). A bare despawn
    /// without the spill would erase in-flight cargo from the
    /// per-tick census: the old destroy/rebuild "disappearing mana"
    /// leak.
    #[test]
    fn castle_total_death_demolishes_balloons_spilling_cargo() {
        let mut w = bare_creature_world(2);
        w.g.move_relink(1, 30 << 8, 30 << 8, 3200);
        let pose = PlayerPose::level(90 << 8, 90 << 8, 3400, 0);
        let c = w.g.spawn_castle(140 << 8, 140 << 8).unwrap();
        w.g.ent[c].id24 = PLAYER_TARGET;
        w.g.ent[c].f144 = PLAYER_TARGET;
        // The spawned castle settles ESTABLISHED at level 1, whose
        // fleet quota is one balloon (FLEET[1]).
        for _ in 0..80 {
            w.tick(pose, PlayerCommand::default());
        }
        let b = (1..w.g.ent.len())
            .find(|&j| {
                let e = &w.g.ent[j];
                e.class64 == 3 && e.model65 == 3 && e.flags & 0x400 == 0
            })
            .expect("the level-1 fleet spawned a balloon");
        // Load the balloon with cargo and park it MID-FLIGHT, well
        // away from the castle, so the cargo is airborne (not yet
        // deposited) when the castle dies.
        w.g.move_relink(b, 100 << 8, 100 << 8, 4000);
        w.g.ent[b].f140 = 7_000;
        w.g.ent[b].f146 = 0;
        let balls_before = count(&w, 10, 39);
        // Demolish: level 1 → total destruction, castle-less.
        w.tick(
            pose,
            PlayerCommand {
                demolish: true,
                ..Default::default()
            },
        );
        for _ in 0..4 {
            w.tick(pose, PlayerCommand::default());
        }
        assert!(w.loadout().castle.is_none(), "the demolish razed it");
        assert_eq!(count(&w, 3, 3), 0, "the castle-less fleet is demolished");
        assert!(
            count(&w, 10, 39) > balls_before,
            "the demolished cargo spilled as a ball"
        );
        assert!(
            w.loadout().mana_max >= 7_000 + WIZARD_BASE_MANA,
            "the census keeps the cargo: no destroy/rebuild leak"
        );
    }

    /// The first-castle lockout (DEVIATIONS.md "the castle-cost stale
    /// stamp"), retail law in every arm since the `castle_recast_cost`
    /// patch was retired (2026-09-07). While housed the castle tick
    /// re-stamps the manifestation's +136 every tick; at castle death
    /// retail's teardown re-stamps the token at CAP[0] = 5000
    /// (sub_47A70 :56527-28 → sub_47C60 case 0 — corroborated by the
    /// cast-phase corpus's token +140 = 49 = 5000/101) — so the
    /// homeless recast prices at 5000, not the stale ladder price.
    #[test]
    fn first_castle_lockout_stale_stamp() {
        let mut w = bare_creature_world(2);
        w.g.move_relink(1, 30 << 8, 30 << 8, 3200);
        let pose = PlayerPose::level(90 << 8, 90 << 8, 3400, 0);
        w.set_dev_spells(true); // grants the book, incl. spell 16
        w.grant_all_spells();
        let c = w.g.spawn_castle(140 << 8, 140 << 8).unwrap();
        w.g.ent[c].id24 = PLAYER_TARGET;
        w.g.ent[c].f144 = PLAYER_TARGET;
        for _ in 0..80 {
            w.tick(pose, PlayerCommand::default());
        }
        let cap1 = crate::engine::features::Gen::CASTLE_CAP[1] as u32;
        let m = w.player.owned[16] as usize;
        assert_ne!(m, 0, "the dev grant materialized the manifestation");
        assert_eq!(
            w.g.ent[m].f136 as u32, cap1,
            "the castle tick stamps the manifestation's +136 to CAP[level]"
        );
        assert_eq!(
            w.spell_cast_cost(16),
            cap1,
            "housed: the stale stamp IS the live law"
        );

        // Demolish: level 1 -> total destruction, castle-less.
        w.tick(
            pose,
            PlayerCommand {
                demolish: true,
                ..Default::default()
            },
        );
        for _ in 0..4 {
            w.tick(pose, PlayerCommand::default());
        }
        assert!(w.loadout().castle.is_none(), "the demolish razed it");

        // Retail arm (the default): the teardown re-stamped CAP[0] =
        // 5000 — the homeless recast prices at 5000 whatever level
        // the dead castle held. The HUD dots (loadout) read the same
        // word, so they show it too.
        let cap0 = crate::engine::features::Gen::CASTLE_CAP[0] as u32;
        assert_eq!(
            w.g.ent[m].f136 as u32, cap0,
            "the teardown stamps the token at CAP[0]"
        );
        assert_eq!(
            w.spell_cast_cost(16),
            cap0,
            "retail arm: the death stamp prices the homeless recast"
        );
        assert_eq!(w.loadout().cost[16], cap0, "the HUD dots agree");
    }

    /// The dispatcher's over-quota cull (:56399-411): when the fleet
    /// quota shrinks below the live balloon count (downgrade, or a
    /// rebuild at a lower level re-adopting released balloons), the
    /// excess balloons are FREED — cargo first spilled as an owned
    /// (10,39) ball (sub_27690), so the census total is conserved.
    #[test]
    fn balloon_cull_over_quota_spills_the_cargo() {
        let mut w = bare_creature_world(2);
        reseat_carpet_above(&mut w);
        w.g.move_relink(1, 30 << 8, 30 << 8, 3200);
        let pose = PlayerPose::level(90 << 8, 90 << 8, 3400, 0);
        let c = w.g.spawn_castle(140 << 8, 140 << 8).unwrap();
        w.g.ent[c].id24 = PLAYER_TARGET;
        w.g.ent[c].f144 = PLAYER_TARGET;
        // Settle at level 1 (fleet quota 1)...
        for _ in 0..80 {
            w.tick(pose, PlayerCommand::default());
        }
        assert_eq!(count(&w, 3, 3), 1, "the quota-1 fleet");
        // ...then forge a SECOND owned balloon carrying cargo (the
        // released-orphan shape a rebuild re-adopts) on a fresh slot.
        let b = w.g.spawn_mana_ball(100 << 8, 100 << 8, 4000).unwrap();
        {
            let e = &mut w.g.ent[b];
            e.class64 = 3;
            e.model65 = 3;
            e.id24 = PLAYER_TARGET;
            e.f144 = PLAYER_TARGET;
            e.f140 = 5_000;
            e.f146 = 0;
        }
        let balls_before = count(&w, 10, 39);
        // Two ticks cover a full every-other-tick dispatcher pass.
        for _ in 0..2 {
            w.tick(pose, PlayerCommand::default());
        }
        assert_eq!(count(&w, 3, 3), 1, "the excess balloon was culled");
        assert!(
            count(&w, 10, 39) > balls_before,
            "the culled cargo spilled as a ball"
        );
        assert!(
            w.loadout().mana_max >= 5_000 + WIZARD_BASE_MANA,
            "the census keeps the culled cargo"
        );
    }

    /// A lethal (here the demolish key) landing MID-TRANSFORMATION must
    /// defer until the castle is established — the original's standing
    /// tick is the only damage processor. Processing it under a live
    /// painter collapses the footprint while the painter keeps
    /// painting, leaving castle terrain with no castle.
    #[test]
    fn demolish_during_the_build_defers_until_established() {
        let mut w = bare_creature_world(2);
        w.g.move_relink(1, 30 << 8, 30 << 8, 3200);
        let pose = PlayerPose::level(90 << 8, 90 << 8, 3400, 0);
        let c = w.g.spawn_castle(140 << 8, 140 << 8).unwrap();
        w.g.ent[c].id24 = PLAYER_TARGET;
        w.g.ent[c].f144 = PLAYER_TARGET;
        // Two ticks in: the painter is mid-flight, the castle waits.
        w.tick(pose, PlayerCommand::default());
        w.tick(pose, PlayerCommand::default());
        assert_eq!(w.g.ent[c].f59, 1, "mid-transformation wait state");
        w.tick(
            pose,
            PlayerCommand {
                demolish: true,
                ..Default::default()
            },
        );
        assert!(w.g.ent[c].act_life < 0, "the lethal is pending");
        // The transformation runs to completion untouched...
        for _ in 0..10 {
            w.tick(pose, PlayerCommand::default());
            if w.g.ent[c].flags & 0x400 != 0 || w.g.ent[c].class64 != 3 {
                panic!("the castle died mid-transformation");
            }
        }
        // ...and the deferred lethal razes it once established
        // (level 1 → destruction).
        for _ in 0..80 {
            w.tick(pose, PlayerCommand::default());
        }
        assert_eq!(count(&w, 3, 2), 0, "processed at establishment");
        // No orphaned painters/levelers keep running afterwards.
        assert_eq!(count(&w, 10, 42) + count(&w, 10, 41), 0);
    }

    #[test]
    fn final_destruction_marks_the_terrain_dirty() {
        // The un-stamp runs inside castle_tick — with no follow-up
        // painter at the final destruction, the renderer only learns
        // of the flattened tower through the Gen terrain_dirty merge.
        // Height assertions live in the real-BUILD.DAT integration test
        // (tests/spell_castle.rs).
        let mut w = flat_world();
        reseat_carpet_above(&mut w);
        let c = w.g.spawn_castle(110 << 8, 110 << 8).unwrap();
        w.g.ent[c].id24 = PLAYER_TARGET;
        w.g.ent[c].f144 = PLAYER_TARGET;
        for _ in 0..80 {
            w.tick(away(), PlayerCommand::default());
        }
        assert_eq!(w.loadout().castle.map(|(_, _, l)| l), Some(1));
        w.terrain_dirty = false;
        w.tick(
            away(),
            PlayerCommand {
                demolish: true,
                ..Default::default()
            },
        );
        // The demolish word lands at the WIZARD PASS (above the
        // castle's slot in the walk) — the castle tick reacts the
        // next frame, retail's own ordering — and that reaction is
        // only the action-6 park; the leveler that actually razes the
        // footprint runs the frame after (sub_470E0 :56138).
        w.tick(away(), PlayerCommand::default());
        assert_eq!(w.g.ent[c].tick70, 6, "parked for the leveler");
        assert!(!w.terrain_dirty, "nothing razed on the park tick");
        w.tick(away(), PlayerCommand::default());
        assert!(
            w.terrain_dirty,
            "the destruction tick re-uploads the flattened footprint"
        );
        for _ in 0..40 {
            w.tick(away(), PlayerCommand::default());
        }
        assert_eq!(count(&w, 3, 2), 0, "the castle is gone");
    }

    #[test]
    fn fireball_kills_and_the_corpse_drops_a_mana_ball() {
        let mut w = bare_creature_world(2);
        rapid_fire(&mut w);
        assert_eq!(count(&w, 5, 2), 1, "the creature spawned");
        // Hold fire from the firing line: the aim assist locks on,
        // the fire's 400-damage broadcast whittles the 3000 life.
        let fire = PlayerCommand {
            fire_left: true,
            ..Default::default()
        };
        let mut died_at = None;
        for t in 0..600 {
            w.tick(firing_line(), fire);
            if count(&w, 5, 2) == 0 {
                died_at = Some(t);
                break;
            }
        }
        assert!(died_at.is_some(), "the creature dies under fire");
        // The corpse dropped its mana ball (life/2 = 1500 mana).
        for _ in 0..16 {
            w.tick(firing_line(), PlayerCommand::default());
        }
        assert!(count(&w, 10, 39) >= 1, "a mana ball dropped");
        // The drop births target_yaw 0 (sub_27690 writes only +30;
        // the port used to mirror f34 = the launch yaw — the mc1l0
        // pair-564 (10,39) family).
        let bslot = find_slot(&w, 10, 39);
        assert_ne!(w.g.ent[bslot].f30, 0, "the launch yaw draw landed");
        assert_eq!(w.g.ent[bslot].f34, 0, "target yaw is born 0");
        // Ball size class by mana (sub_274D0): the lunger's 1500
        // (life/2) lands in class 3 → sprite type 55.
        let ball = w
            .live_poses()
            .into_iter()
            .find(|p| p.class == 10 && p.model == 39)
            .expect("ball pose");
        assert_eq!(ball.type_index, 55, "1500 mana = size class 3");
        let (kills, shots, _hits) = w.combat_stats();
        assert_eq!(kills, 1, "the kill credits the player");
        assert!(shots > 0, "shots were resolved");
    }

