    // ---- player spells ------------------------------------------------------

    #[test]
    fn casting_fireball_spawns_a_projectile_and_deducts_mana() {
        let mut w = flat_world();
        // A fresh world's book is EMPTY (the retail human grant is
        // availability ∩ collected — no campaign store, no spells).
        let lv = w.loadout();
        assert!(!lv.owned.iter().any(|&o| o), "fresh book starts empty");
        assert_eq!((lv.left, lv.right), (None, None));
        seat_carpet_if_absent(&mut w);
        w.grant_spells(&[0, 3]);
        let lv = w.loadout();
        assert!(lv.owned[0] && lv.owned[3], "granted");
        assert_eq!(
            (lv.left, lv.right),
            (Some(0), Some(3)),
            "auto-fill L/R (:49246-54)"
        );
        let fire = PlayerCommand {
            fire_left: true,
            ..Default::default()
        };
        w.tick(firing_line(), fire);
        // ⚖ THE CAST PHASE IS SLOT-RELATIVE (round 162, w162a): the
        // press ARMS at the CARPET's walk slot and the token FIRES at
        // its OWN, in one ascending pass. This fixture's carpet is the
        // constructor's, with the granted book ABOVE it — retail's own
        // level-start order — so the token is reached later in the
        // SAME tick and fires on the press. Retail witness: mc1l3 t=7,
        // token 581 over carpet 579, armed and fired together.
        assert_eq!(count(&w, 9, 0), 1, "the press tick arms AND fires");
        // ⚖ THE MANA PHASE MOVES WITH IT, THE OPPOSITE WAY. The token
        // STAMPS the delta (sub_55E80) and the WIZARD PASS applies it —
        // and the wizard pass already ran this tick, at the carpet's
        // slot below. So an above-carpet token's debit surfaces at
        // press+1: mc1l3 carpet 579 reads `f132` 100 -> -50 at t=7
        // with `f140` still 1000, then `f140` 1000 -> 950 at t=8. (The
        // old "debit landed with the spawn" reading is the BELOW-
        // carpet expression, from the l0 trace.)
        assert_eq!(w.loadout().mana, 1000, "no debit at the command site");
        assert!(w.loadout().cooldown[0] > 0.0, "burst window armed");
        w.tick(firing_line(), fire); // held: edge-triggered, no refire
        assert_eq!(count(&w, 9, 0), 1, "fireball is EDGE-triggered: still one");
        assert_eq!(
            w.loadout().mana,
            800,
            "the full 200 debit surfaces at press+1"
        );
        // Fireball is EDGE-triggered (autofire is spell 23's alone):
        // holding adds nothing; a fresh press past the burst does.
        for _ in 0..8 {
            w.tick(firing_line(), fire);
        }
        assert_eq!(
            count(&w, 9, 0) + w.combat_stats().1 as usize,
            1,
            "held fire never re-casts"
        );
        w.tick(firing_line(), PlayerCommand::default()); // release
        w.tick(firing_line(), fire); // re-press: arms
        w.tick(firing_line(), fire); // the token fires
        let total = count(&w, 9, 0) + w.combat_stats().1 as usize;
        assert_eq!(total, 2, "release + re-press casts again (at arm+1)");
        // Below the possess gate nothing fires.
        let mut w2 = flat_world();
        w2.player.mana = 100;
        w2.tick(firing_line(), fire);
        assert_eq!(count(&w2, 9, 0), 0, "mana-gated cast");
    }

    #[test]
    fn jar_pickup_grants_auto_equips_and_keeps_the_slot() {
        let planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        // A class-12 jar carrying spell 7 (Meteor) via its model.
        let things = vec![Thing {
            slot: 0,
            kind: ThingKind::Entity,
            class: 12,
            model: 7,
            x: 112,
            y: 116,
            dis_id: 0,
            swi_sz: 0,
            swi_id: 0,
            parent: 0,
            child: 0,
            par3: None,
        }];
        let mut w = World::new(planes, &things, 1, assets());
        assert!(!w.loadout().owned[7]);
        assert_eq!(w.live_poses().iter().filter(|p| p.class == 12).count(), 1);
        let (free0, _) = w.debug_pool();
        // Fly onto the jar (ground 100*32 = 3200 engine units).
        let on_jar = PlayerPose::level((112 << 8) + 128, (116 << 8) + 128, 3260, 0);
        for _ in 0..4 {
            w.tick(on_jar, PlayerCommand::default());
        }
        let lv = w.loadout();
        assert!(lv.owned[7], "the jar granted its spell");
        assert_eq!(lv.left, Some(7), "auto-equipped LEFT (:64855)");
        let (free1, _) = w.debug_pool();
        assert_eq!(free0, free1, "the manifestation keeps the jar's pool slot");
        assert!(
            w.live_poses().iter().all(|p| p.class != 12),
            "the picked-up jar no longer renders"
        );
        // :64851 — the in-place conversion stamps the OWNED bit on
        // the jar record (round 154, w154d; `MGC_NO_MC1_HUMAN_TOKEN_CTOR=1`
        // must fail this line).
        let m = w.player.owned[7] as usize;
        assert_eq!(w.g.ent[m].flags & 1, 1, "the converted jar wears `+16` bit 0");
        // Re-overlap: no duplicate, the manifestation stays (:64843).
        for _ in 0..4 {
            w.tick(on_jar, PlayerCommand::default());
        }
        assert_eq!(w.debug_pool().0, free1);
    }

    /// In play a resting jar rides its tile's ground — the ruled
    /// deviation (DEVIATIONS.md "class12_tick jar ground-snap"): HW
    /// authors jars that later shaping buries unpickably, and
    /// earth-shaping spells would leave jars floating. In
    /// strict-retail mode (conformance imports) the snap is OFF:
    /// retail's reshape walk default-skips class 12 (:51729) and the
    /// HW recordings show a jar holding its z for hundreds of ticks
    /// over lowered ground — replayed retail state must do the same.
    #[test]
    fn jars_ride_terrain_in_play_but_not_under_strict_retail() {
        let planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        let things = vec![Thing {
            slot: 0,
            kind: ThingKind::Entity,
            class: 12,
            model: 7,
            x: 200,
            y: 200,
            dis_id: 0,
            swi_sz: 0,
            swi_id: 0,
            parent: 0,
            child: 0,
            par3: None,
        }];
        let mut w = World::new(planes, &things, 1, assets());
        w.set_patches(crate::patches::WorldPatches::LEGACY);
        let away = PlayerPose::level(10 << 8, 10 << 8, 3260, 0);
        w.tick(away, PlayerCommand::default());
        let jar = (1..w.g.ent.len())
            .find(|&i| w.g.ent[i].class64 == 12 && w.g.ent[i].flags & 0x400 == 0)
            .expect("the placed jar exists");
        let (x, y) = (w.g.ent[jar].x, w.g.ent[jar].y);
        assert_eq!(
            w.g.ent[jar].z,
            w.g.ground_z(x, y) as i16,
            "spawns on ground"
        );

        // Raise the ground under it: in play the jar rides up.
        let (tx, ty) = ((x >> 8) as usize, (y >> 8) as usize);
        for dy in 0..2 {
            for dx in 0..2 {
                w.g.t.height[(ty + dy) % 256 * 256 + (tx + dx) % 256] = 140;
            }
        }
        w.tick(away, PlayerCommand::default());
        assert_eq!(
            w.g.ent[jar].z,
            w.g.ground_z(x, y) as i16,
            "raised ground lifts the jar in play"
        );
        let riding_z = w.g.ent[jar].z;

        // Strict-retail (a conformance import replay): the snap is
        // off — lowering the ground leaves the jar hovering at its
        // old z, exactly like the retail recordings.
        w.strict_retail = true;
        for dy in 0..2 {
            for dx in 0..2 {
                w.g.t.height[(ty + dy) % 256 * 256 + (tx + dx) % 256] = 40;
            }
        }
        w.tick(away, PlayerCommand::default());
        assert_eq!(
            w.g.ent[jar].z, riding_z,
            "strict-retail keeps the jar hovering at its old z"
        );

        // Back in play mode the snap resumes and drops it to ground.
        w.strict_retail = false;
        w.tick(away, PlayerCommand::default());
        assert_eq!(
            w.g.ent[jar].z,
            w.g.ground_z(x, y) as i16,
            "play mode re-grounds it"
        );
    }

    /// ⭐⭐ A FULL ACQUISITION LIST REFUSES THE JAR GRANT — the
    /// NATIVE call path of `sub_55A40_55F70` (:64818-41). The scan
    /// keeps two results in one walk: `v25` (the list already holds a
    /// class-12 record of this spell) and `v24`, the index of the
    /// FIRST EMPTY seat, initialised to −1; `:64841` refuses the whole
    /// grant on `v25 || v24 == -1`, because `v24` is both the seat the
    /// pool slot is written into (`+532 + 4*v24`, :64850) and the
    /// value stamped into the left hand (`+940 = v24`, :64851).
    ///
    /// A seat holds a RAW pool slot with no liveness test, so a
    /// recycled slot leaves a ZOMBIE seat that is neither empty
    /// (`slot != 0`) nor a class-12 match — the list can be full with
    /// the spell still unowned. That is mc1l49's state at t=18525
    /// (24/24 seats taken, seat 20 naming the freed slot 235,
    /// `+676[20] = 0`) and the recorded jar there is never picked up;
    /// the fixture `a-full-acquisition-list-refuses-the-grant-retail`
    /// pins the strict-retail arm, this pins the native one.
    ///
    /// `MGC_NO_MC1_ACQ_LIST_FULL=1` restores the pre-dig grant and
    /// FAILS this test. The `no_spell_loss` patch is the relief arm —
    /// it scrubs the zombie seats in native play — so the test runs on
    /// `WorldPatches::LEGACY`, retail's own behaviour.
    #[test]
    fn a_full_acquisition_list_refuses_the_jar_grant() {
        let planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        let things = vec![Thing {
            slot: 0,
            kind: ThingKind::Entity,
            class: 12,
            model: 7,
            x: 200,
            y: 200,
            dis_id: 0,
            swi_sz: 0,
            swi_id: 0,
            parent: 0,
            child: 0,
            par3: None,
        }];
        let mut w = World::new(planes, &things, 1, assets());
        w.set_patches(crate::patches::WorldPatches::LEGACY);
        let away = PlayerPose::level(10 << 8, 10 << 8, 3260, 0);
        w.tick(away, PlayerCommand::default());
        let jar = (1..w.g.ent.len())
            .find(|&i| w.g.ent[i].class64 == 12 && w.g.ent[i].flags & 0x400 == 0)
            .expect("the placed jar exists");
        let (jx, jy, jz) = (w.g.ent[jar].x, w.g.ent[jar].y, w.g.ent[jar].z);
        let on_jar = PlayerPose::level(jx, jy, jz, 0);
        assert_eq!(w.player.owned[7], 0, "spell 7 starts unowned");

        // Fill every empty seat with a ZOMBIE: a non-zero slot whose
        // pool record is FREE, so `v24` stays −1 and `v25` stays 0.
        let mut z = w.g.ent.len() - 1;
        for k in 0..w.mc1_acq.len() {
            if w.mc1_acq[k] > 0 {
                continue;
            }
            while w.g.ent[z].class64 != 0 {
                z -= 1;
            }
            w.mc1_acq[k] = z as i32;
            z -= 1;
        }
        assert!(w.mc1_acq.iter().all(|&e| e > 0), "the list is 24/24 full");

        w.tick(on_jar, PlayerCommand::default());
        assert_eq!(
            w.g.ent[jar].tick70, 0,
            "the full list refuses the grant: the jar keeps its phase"
        );
        assert_eq!(w.player.owned[7], 0, "and the spell stays unowned");
        assert_ne!(w.player.left, Some(crate::mc1::spells::SpellId(7)));

        // Free ONE seat — `v24` now names it — and the same overlap
        // grants on the very next poll.
        w.mc1_acq[23] = 0;
        w.tick(on_jar, PlayerCommand::default());
        assert_eq!(
            w.g.ent[jar].tick70,
            MANIFEST_BASE + 7,
            "one free seat is enough: the jar converts in place"
        );
        assert_eq!(w.player.owned[7], jar as u16);
        assert_eq!(w.player.left, Some(crate::mc1::spells::SpellId(7)));
    }

    /// The jar ground-snap deviation over real content: on baked HW
    /// level 0 (the original buried-jar offender) every placed jar
    /// sits AT the shaped ground within one played tick — never
    /// buried under shaping, never hovering. Self-skips without
    /// baked data.
    #[test]
    fn hw_placed_jars_sit_on_ground_in_play() {
        let root = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../baked");
        let lp = root.join("mc1hw/level-000.mgcl");
        if !lp.exists() {
            return;
        }
        let pkg: mgc_formats::LevelPackage =
            mgc_formats::mgcl::read(std::fs::File::open(lp).unwrap()).unwrap();
        let bundle = mgc_formats::bundle::Bundle::load(&root.join("assets/mc1-arctic")).unwrap();
        let terrain = pkg.terrain.as_ref().unwrap();
        let planes = Planes {
            height: terrain.height.clone(),
            tile_type: terrain.tile_type.clone(),
            shading: terrain.shading.clone().unwrap(),
            angle: terrain.angle.clone().unwrap(),
            ceiling: Vec::new(),
        };
        let assets = FeatureAssets::parse(
            bundle.search.as_ref().unwrap(),
            bundle.build_tab.as_ref().unwrap(),
            bundle.build_dat.as_ref().unwrap(),
        )
        .unwrap();
        let seed = pkg.gen_params.as_ref().map_or(0, |g| g.seed);
        let mut w = World::new_for_game(planes, &pkg.things.things, seed, assets, GameId::Mc1Hw);
        let away = PlayerPose::level(10 << 8, 10 << 8, 3260, 0);
        w.tick(away, PlayerCommand::default());
        let mut jars = 0;
        for i in 1..w.g.ent.len() {
            let e = &w.g.ent[i];
            if e.class64 == 12 && e.flags & 0x400 == 0 {
                jars += 1;
                assert_eq!(
                    e.z,
                    w.g.ground_z(e.x, e.y) as i16,
                    "jar slot {i} at ({}, {}) sits on shaped ground",
                    e.x,
                    e.y
                );
            }
        }
        assert!(jars > 0, "level 0 places jars");
    }

    /// The dev cheat is an OVERLAY (player ruling 2026-09-15, see
    /// [`World::set_dev_spells`]): switching it on mints nothing and
    /// hides no jar; binding an unowned spell mints its token on demand
    /// and STILL leaves the jar drawn; switching it off takes back
    /// exactly the on-demand mints — slot freed, acquisition entry
    /// gone, hand emptied — and leaves the earned book alone.
    #[test]
    fn dev_spells_overlay_mints_on_bind_and_takes_it_back_mc1() {
        use crate::mc1::spells::SpellId;
        let planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        let things = vec![Thing {
            slot: 0,
            kind: ThingKind::Entity,
            class: 12,
            model: 7,
            x: 200,
            y: 200,
            dis_id: 0,
            swi_sz: 0,
            swi_id: 0,
            parent: 0,
            child: 0,
            par3: None,
        }];
        let mut w = World::new(planes, &things, 1, assets());
        w.grant_spell(SpellId(3)); // an EARNED spell
        let drawn = |w: &World| w.live_things().iter().filter(|t| t.class == 12).count();
        let tokens = |w: &World| {
            w.g.ent
                .iter()
                .filter(|e| e.class64 == 12 && e.tick70 >= MANIFEST_BASE)
                .count()
        };
        let free0 = w.debug_pool().0;
        assert_eq!(tokens(&w), 1);
        w.set_dev_spells(true);
        assert_eq!(tokens(&w), 1, "the toggle mints nothing");
        assert_eq!(w.debug_pool().0, free0);
        assert_eq!(drawn(&w), 1, "the jar is still drawn");
        assert!(!w.loadout().owned[7]);
        // Bind spell 7 (the jar's) and spell 9 (no jar) under the cheat.
        w.equip_hands(Some(SpellId(7)), Some(SpellId(9)));
        let lv = w.loadout();
        assert!(lv.owned[7] && lv.owned[9], "minted on bind");
        assert_eq!((lv.left, lv.right), (Some(7), Some(9)));
        assert_eq!(tokens(&w), 3);
        assert!(w.dev_minted(7) && w.dev_minted(9) && !w.dev_minted(3));
        assert_eq!(drawn(&w), 1, "a dev-minted hold does not hide the jar");
        let away = PlayerPose::level(10 << 8, 10 << 8, 3260, 0);
        for _ in 0..4 {
            w.tick(away, PlayerCommand::default());
        }
        assert!(w.loadout().owned[7], "the per-tick rebuild keeps the mint (it is listed)");
        assert_eq!(drawn(&w), 1);
        w.set_dev_spells(false);
        let lv = w.loadout();
        assert!(lv.owned[3], "the earned spell stays");
        assert!(!lv.owned[7] && !lv.owned[9], "the dev mints are gone");
        assert_eq!((lv.left, lv.right), (None, None), "their hands are emptied");
        assert_eq!(tokens(&w), 1, "their records are freed");
        assert_eq!(w.debug_pool().0, free0, "and back on the free list");
        assert_eq!(w.dev_minted, 0);
        for _ in 0..4 {
            w.tick(away, PlayerCommand::default());
        }
        assert!(!w.loadout().owned[7], "the acquisition list no longer names them");
        assert!(w.loadout().owned[3]);
        assert_eq!(drawn(&w), 1, "the jar is still there to collect");
    }

    /// Collecting the jar of a spell the cheat had minted CONVERTS it:
    /// the dev token goes, the jar becomes the earned manifestation
    /// (retail's own pickup law), the hand keeps the spell, and the
    /// toggle-off leaves it alone.
    #[test]
    fn dev_spells_jar_pickup_converts_the_dev_mint_mc1() {
        use crate::mc1::spells::SpellId;
        let planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        let things = vec![Thing {
            slot: 0,
            kind: ThingKind::Entity,
            class: 12,
            model: 7,
            x: 112,
            y: 116,
            dis_id: 0,
            swi_sz: 0,
            swi_id: 0,
            parent: 0,
            child: 0,
            par3: None,
        }];
        let mut w = World::new(planes, &things, 1, assets());
        let free0 = w.debug_pool().0;
        w.set_dev_spells(true);
        w.equip_hands(Some(SpellId(7)), None);
        let dev_tok = w.player.owned[7] as usize;
        assert_ne!(dev_tok, 0);
        assert!(w.dev_minted(7));
        assert_eq!(w.debug_pool().0, free0 - 1);
        assert_eq!(
            w.live_things().iter().filter(|t| t.class == 12).count(),
            1,
            "the jar is drawn under the cheat"
        );
        let on_jar = PlayerPose::level((112 << 8) + 128, (116 << 8) + 128, 3260, 0);
        for _ in 0..4 {
            w.tick(on_jar, PlayerCommand::default());
        }
        assert!(!w.dev_minted(7), "converted to an earned acquisition");
        let tok = w.player.owned[7] as usize;
        assert_ne!(tok, 0);
        assert_ne!(tok, dev_tok, "the jar's own record is the token now");
        assert_eq!(w.g.ent[tok].class64, 12);
        assert_eq!(w.debug_pool().0, free0, "the dev token's slot was freed");
        assert_eq!(w.loadout().left, Some(7));
        assert!(w.mc1_acq.iter().all(|&e| e != dev_tok as i32));
        w.set_dev_spells(false);
        assert!(w.loadout().owned[7], "an earned spell survives the toggle");
        assert_eq!(w.loadout().left, Some(7));
    }

    /// The MC2 arm of the overlay: the toggle mints nothing, a select
    /// under it mints on demand, and the toggle-off frees that token,
    /// clears the book slot and the hand, and leaves the seeded book
    /// alone.
    #[test]
    fn dev_spells_overlay_mints_on_select_and_takes_it_back_mc2() {
        let mut w = mc2_flat_world();
        let mut bytes = vec![0u8; 26 * 80];
        for sp in 0..26 {
            let b = 80 * sp + 2;
            bytes[b..b + 4].copy_from_slice(&250i32.to_le_bytes());
            bytes[b + 4..b + 8].copy_from_slice(&10i32.to_le_bytes());
            bytes[b + 22] = 5;
        }
        bytes[0] = 3;
        w.g.assets.spells = crate::mc2::spells::parse(&bytes).unwrap();
        let seeded = w.mc2_book.ent;
        assert_ne!(seeded[0], 0, "the {{0,1}} seed");
        let hands = (w.mc2_book.left, w.mc2_book.right);
        let free0 = w.debug_pool().0;
        w.set_dev_spells(true);
        assert_eq!(w.mc2_book.ent, seeded, "the toggle mints nothing");
        assert_eq!(w.debug_pool().0, free0);
        w.mc2_select_spell(5, 0, 0); // HEAL onto the LEFT hand
        let tok = w.mc2_book.ent[5] as usize;
        assert_ne!(tok, 0, "minted on select");
        assert!(w.dev_minted(5));
        assert_eq!(w.mc2_book.left, 5);
        assert_eq!(w.player.left.map(|s| s.0), Some(5), "the mirror follows");
        w.set_dev_spells(false);
        assert_eq!(w.mc2_book.ent[5], 0, "the book slot is cleared");
        assert!(!w.dev_minted(5));
        assert_eq!(w.g.ent[tok].class64, 0, "the token is freed");
        assert_eq!(w.debug_pool().0, free0);
        assert_eq!(w.mc2_book.left, -1, "the hand is emptied");
        assert_eq!(w.player.left, None);
        assert_eq!(w.mc2_book.right, hands.1, "the other hand is untouched");
        assert_eq!(w.mc2_book.ent[0], seeded[0], "the seeded book is untouched");
        assert_eq!(w.mc2_book.ent[1], seeded[1]);
    }

    /// v21: the dev cheat's on-demand mint set rides the snapshot, so a
    /// resume cannot turn lent spells into earned ones.
    #[test]
    fn v21_dev_minted_survives_a_snapshot_round_trip() {
        let mut a = crate::Simulation::with_world(flat_world());
        a.world.as_mut().unwrap().dev_minted = 0b1010;
        let bytes = a.snapshot();
        let mut b = crate::Simulation::with_world(flat_world());
        b.restore(&bytes).expect("identical world, same build");
        assert_eq!(b.world.as_ref().unwrap().dev_minted, 0b1010);
    }

    fn flat_planes(tile_type: u8) -> Planes {
        Planes {
            height: vec![100; 0x10000],
            tile_type: vec![tile_type; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        }
    }

    /// GHOST MODE (player-set 2026-09-15, [`World::set_ghost`]): the
    /// cloak mirror every scan reads is true on every tick while the
    /// cheat is on, a cast does not break it (the spell latch is not
    /// involved at all), and switching it off uncloaks again.
    #[test]
    fn ghost_mode_cloaks_the_human_through_a_cast_mc1() {
        let mut w = flat_world();
        w.set_dev_spells(true);
        w.grant_all_spells();
        w.tick(firing_line(), PlayerCommand::default());
        assert!(!w.g.player_invisible, "uncloaked without the cheat");
        w.set_ghost(true);
        w.tick(firing_line(), PlayerCommand::default());
        assert!(w.g.player_invisible, "the mirror reads cloaked");
        assert!(!w.player.invisible, "…with the spell latch untouched");
        // A cast runs `break_cloak` — the cheat does not care.
        w.tick(
            firing_line(),
            PlayerCommand {
                fire_left: true,
                ..Default::default()
            },
        );
        w.tick(firing_line(), PlayerCommand::default());
        assert_eq!(count(&w, 9, 0), 1, "fixture: the cast went out");
        assert!(w.g.player_invisible, "a cast does not break ghost mode");
        assert!(w.g.player_ghost.0, "the see-through scans' own gate");
        w.set_ghost(false);
        w.tick(firing_line(), PlayerCommand::default());
        assert!(!w.g.player_invisible && !w.g.player_ghost.0, "off: uncloaked again");
    }

    /// GHOST MODE flies over MC1's type-8 walls as if they were
    /// terrain — on the very inside corner that refuses an ordinary
    /// carpet, both gates commit the proposal unchanged.
    #[test]
    fn ghost_mode_flies_over_mc1_walls() {
        let mut planes = flat_planes(5);
        for y in 0..=255 {
            planes.tile_type[tile(120, y)] = 8;
        }
        for x in 0..=255 {
            planes.tile_type[tile(x, 101)] = 8;
        }
        let mut w = World::new(planes, &[], 1, assets());
        let cur = (119 * 256 + 205, 100 * 256 + 205, 3200);
        let prop = (120 * 256 + 51, 101 * 256 + 51, 3200);
        let from = (119.95, 99.5, 12.5);
        let to = (120.85, 99.9, 12.5);
        assert!(!w.player_wall_gate_fixed(cur, prop).0, "fixture: the corner refuses");
        assert!(
            w.player_wall_gate(from, to).is_some_and(|p| p.0 < 120.0),
            "fixture: the float gate slides along the wall"
        );
        w.set_ghost(true);
        assert_eq!(w.player_wall_gate_fixed(cur, prop), (true, prop));
        assert_eq!(w.player_wall_gate(from, to), Some(to));
    }

    /// GHOST MODE on the MC2 column: the deep-water barrier of
    /// `moveTest_5D0A0` is terrain — the move commits, nothing reads
    /// wet, and the wedged test no longer fires.
    #[test]
    fn ghost_mode_flies_over_mc2_deep_water() {
        let mut w = World::new_for_game(flat_planes(8), &[], 1, assets(), GameId::Mc2);
        let cur = (100 * 256, 100 * 256, 3300);
        let prop = (100 * 256 + 100, 100 * 256 + 100, 3300);
        let out = w.player_mc2_gate(cur, prop);
        assert!(out.wet && out.pass.is_none(), "fixture: an all-water world refuses");
        assert!(w.player_mc2_stuck(cur, false), "…and reads wedged");
        w.set_ghost(true);
        let out = w.player_mc2_gate(cur, prop);
        assert!(!out.wet, "no water counter bump");
        assert_eq!(out.pass, Some((prop, 0)), "the move commits unchanged");
        assert!(!w.player_mc2_stuck(cur, false));
    }

