    /// v22: both cheats ride the snapshot like `invincible`.
    #[test]
    fn v22_ghost_and_inert_survive_a_snapshot_round_trip() {
        let mut a = crate::Simulation::with_world(flat_world());
        {
            let w = a.world.as_mut().unwrap();
            w.set_ghost(true);
            w.set_inert(true);
        }
        let bytes = a.snapshot();
        let mut b = crate::Simulation::with_world(flat_world());
        b.restore(&bytes).expect("identical world, same build");
        let w = b.world.as_ref().unwrap();
        assert!(w.ghost() && w.inert());
    }

    /// A placed jar whose spell the player already owns is NOT DRAWN —
    /// retail hides it, so the port hides it too, unconditionally
    /// ([`World::owned_spell_jar`]). This was `..._when_enabled`, an
    /// arm of the retired `prune_owned_jars` option, until the player
    /// ruled the hide retail behaviour on a replay's post-death jar
    /// pile (2026-08-25g).
    #[test]
    fn owned_spell_jars_are_never_drawn() {
        use crate::mc1::spells::SpellId;
        let planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        // A placed class-12 jar carrying spell 7, far from the carpet.
        let things = vec![Thing {
            slot: 0,
            kind: ThingKind::Entity,
            class: 12,
            model: 7,
            x: 200,
            y: 200,
            dis_id: 0,
            swi_sz: 0,
            swi_id: 0,
            parent: 0,
            child: 0,
            par3: None,
        }];
        let jars = |w: &World| {
            w.debug_pool()
                .1
                .into_iter()
                .filter(|e| e.class == 12 && e.state < MANIFEST_BASE && e.flags & 0x400 == 0)
                .count()
        };

        // Faithful default: the jar of an already-owned spell stays.
        let mut keep = World::new(planes.clone(), &things, 1, assets());
        keep.grant_spell(SpellId(7));
        let away = PlayerPose::level(10 << 8, 10 << 8, 3260, 0);
        for _ in 0..8 {
            keep.tick(away, PlayerCommand::default());
        }
        assert_eq!(
            jars(&keep),
            1,
            "off by default: the uncollectable jar remains"
        );

        // ⭐ With the improvement on, the same jar STOPS BEING DRAWN
        // and STAYS IN THE POOL — the painter-layer form, relocated
        // 2026-08-24f. Retail hides an owned-spell jar (byte[0] bit 0)
        // and keeps the record, because the pickup is PER-PLAYER and
        // multiplayer needs it to survive for the other wizards; the
        // old sim-side `flags |= 0x400` was a removal where retail
        // hides, and it perturbed the free stack for no reason.
        // BOTH halves are asserted: absent from the painter, present in
        // the pool. Asserting only the first would pass equally well
        // for the old cull, which is exactly what this test must now
        // distinguish.
        let mut prune = World::new(planes, &things, 1, assets());
        prune.grant_spell(SpellId(7));
        assert_eq!(jars(&prune), 1, "jar present before it ticks");
        let drawn = |w: &World| w.live_things().iter().filter(|t| t.class == 12).count();
        assert_eq!(drawn(&prune), 0, "the owned-spell jar is not drawn");
        for _ in 0..8 {
            prune.tick(away, PlayerCommand::default());
        }
        assert_eq!(drawn(&prune), 0, "still not drawn after ticking");
        assert_eq!(
            jars(&prune),
            1,
            "and the RECORD SURVIVES — retail hides, it does not free"
        );
    }

    /// THE NATIVE JAR POLL STAMPS "ALREADY KNOWN" (round 154, w154k —
    /// [`crate::engine::features::no_mc1_native_jar_known_stamp`]).
    /// `sub_55A40`'s bucket[0] walk (:64784-97, CARPET.EXE VA
    /// 0x55ACD-0x55B14) sets bit 0 on a ground jar whose spell the
    /// local human owns, on every poll tick, with NO distance test —
    /// the strict arm carried it, the native arm did not (`init-check`
    /// mc1l10 slot 2 / l13 99 / l20 28+29: retail `flags 5`, port 4).
    /// A jar of an unowned spell is the control; the record survives
    /// either way (retail hides, it never frees).
    #[test]
    fn the_native_jar_poll_stamps_an_owned_spells_jar_known() {
        use crate::mc1::spells::SpellId;
        let planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        let jar = |slot: u32, model: u16, x: u16| Thing {
            slot,
            kind: ThingKind::Entity,
            class: 12,
            model,
            x,
            y: 200,
            dis_id: 0,
            swi_sz: 0,
            swi_id: 0,
            parent: 0,
            child: 0,
            par3: None,
        };
        // Two authored jars far from the carpet: spell 7 (owned below)
        // and spell 9 (the unowned control).
        let things = vec![jar(0, 7, 200), jar(1, 9, 210)];
        let mut w = World::new(planes, &things, 1, assets());
        w.grant_spell(SpellId(7));
        let find = |w: &World, model: u8| {
            (1..w.g.ent.len())
                .find(|&i| {
                    let e = &w.g.ent[i];
                    // the ground JAR, not the human's minted token
                    e.class64 == 12 && e.model65 == model && e.tick70 < MANIFEST_BASE
                })
                .expect("the authored jar is in the pool")
        };
        let (j7, j9) = (find(&w, 7), find(&w, 9));
        assert_eq!(w.g.ent[j7].flags & 1, 0, "premise: born unstamped");
        assert!(w.g.ent[j7].tick70 <= 2, "premise: a native authored jar");
        let away = PlayerPose::level(10 << 8, 10 << 8, 3260, 0);
        // Four ticks cover every `+63 & 3` poll phase.
        for _ in 0..4 {
            w.tick(away, PlayerCommand::default());
        }
        assert_eq!(
            w.g.ent[j7].flags & 1,
            1,
            "the owned spell's jar carries the already-known bit after its first poll (:64794-97)"
        );
        assert_eq!(w.g.ent[j9].flags & 1, 0, "the unowned spell's jar is never stamped");
        assert_eq!(w.g.ent[j7].class64, 12, "the stamp hides, it does not free");
        assert!(w.g.ent[j7].tick70 <= 2, "…and the jar stays a jar (no conversion)");
        assert_eq!(w.g.ent[j7].flags & 0x400, 0, "…nor reap-flags it");
    }

    #[test]
    fn accelerate_directions_are_mutually_exclusive() {
        use crate::mc1::spells::SpellId;
        let mut w = flat_world();
        // Toggle semantics under test, not the economy — the real
        // pool (base 1000) can't fund back-to-back 1000-cost arms.
        w.set_dev_spells(true);
        w.grant_all_spells();
        // ⚖ LAY THE BOOK OUT **BELOW** THE CARPET (round 162, w162a).
        // The cast phase is slot-relative — arm at the carpet's walk
        // slot, fire at the token's, one ascending pass — so a token
        // BELOW the carpet is only reached on the NEXT lap, which is
        // the two-phase shape this test's mc1l48 t=4899 citation
        // records (retail's `+48` back at 251, re-armed, not fired).
        // Re-seating the carpet above the granted book reproduces that
        // layout; without it the tokens sit above the carpet and the
        // burst ends in the same tick instead.
        reseat_carpet_above(&mut w);
        let equip = PlayerCommand {
            equip_left: Some(SpellId(2)),
            equip_right: Some(SpellId(21)),
            ..Default::default()
        };
        w.tick(away(), equip);
        assert_eq!(w.accel_override(), None, "no override at rest");
        // Forward: ±3.0 while the button is held ("hold down the
        // mouse button to achieve maximum speed").
        let fwd = PlayerCommand {
            fire_left: true,
            ..Default::default()
        };
        w.tick(away(), fwd);
        assert_eq!(w.accel_override(), Some(3.0), "held = 3.0 (:65169)");
        w.tick(away(), fwd);
        assert_eq!(w.accel_override(), Some(3.0), "still held = still 3.0");
        // Released: the channel keeps propelling at 2.0.
        w.tick(away(), PlayerCommand::default());
        assert_eq!(w.accel_override(), Some(2.0), "released = 2.0 channel");
        // Opposite activation force-clears forward (:55871/:55914).
        let back = PlayerCommand {
            fire_right: true,
            ..Default::default()
        };
        w.tick(away(), back);
        assert_eq!(w.player.accel, -1, "backward took over");
        assert_eq!(w.accel_override(), Some(-3.0), "negative held backward");
        let m2 = w.player.owned[2] as usize;
        assert_eq!(w.g.ent[m2].f26, 0, "forward's charge force-cleared");
        // ⭐⭐ THE RESISTING PRESS IS A ONE-PHASE KILL AT THE TOKEN, AND
        // IT DOES NOT VETO THE CAST. This block used to assert the
        // opposite ("the veto blocked the re-arm") — the last residue
        // of the retired `thrust_cancel` deviation. Retail's trigger
        // `sub_46B00_46E40` tests the opposite token's `+48` clear and
        // `+140 >= +136` and nothing else (:55869-77/:55912-18), then
        // LABEL_32 pins `var_48 = var_50` unconditionally (:55893) —
        // and the two calls sit at the TAIL of the very routine that
        // just ran the bounds-tested speed step (:55825-33), with no
        // test of its result in between. So the cancel is the v_14
        // two-phase ALONE: the press moves the flight target
        // (:55766-80), the token reads the latch on its NEXT pass and
        // ends the burst (counter = 1 → 0, :66188-89), and the held
        // command RE-ARMS behind it in the same tick. mc1l48 t=4899
        // records exactly that shape — retail's 0x80 clears while the
        // token's `+48` sits back at 251 — and only t=4900 leaves it
        // at 0, because the input site's held re-issue is gated on a
        // nonzero counter (:20621-27), not on the stick. Pinned lanes
        // have no mover, so the test publishes the latch by hand.
        w.thrust_cancel(1.0);
        assert_eq!(
            w.accel_override(),
            Some(-3.0),
            "the veto alone does not kill the channel"
        );
        w.mc1_v14 = true;
        w.tick(away(), back);
        assert_eq!(
            w.pending_speed_base,
            Some(-80),
            "v_14 ended the burst at the token, restoring the NEGATIVE base (:66226-27)"
        );
        let m21 = w.player.owned[21] as usize;
        assert_eq!(
            w.g.ent[m21].f26, 251,
            "and the held command re-armed behind it — NO cast-site veto (mc1l48 t=4899)"
        );
        assert_eq!(
            w.accel_override(),
            Some(-3.0),
            "so the channel is live again on the same tick"
        );
        w.mc1_v14 = false;
        w.pending_speed_base = None;
        // Next tick (no veto) it channels again, then drains after
        // release (count 251) back to no override.
        w.tick(away(), back);
        assert_eq!(w.accel_override(), Some(-3.0));
        for _ in 0..252 {
            w.tick(away(), PlayerCommand::default());
        }
        assert_eq!(w.accel_override(), None, "expired burst drops the override");
        assert_eq!(w.player_speed_boost(), 0.0);
    }

    /// The sustained Accelerate is NOT free: `sub_55E80` (:64936,
    /// live in remc2 as `sub_68DE0`) debits the full cost on every
    /// tick the burst sits at full, and a dry pool drops the flyer
    /// from 3x to 2x for the rest of the burst instead of cancelling
    /// it. No `dev_spells` here — that pin no-ops both the gate and
    /// the debit, which is exactly how this went unnoticed.
    #[test]
    fn held_accelerate_drains_mana_every_tick() {
        use crate::mc1::spells::SpellId;
        let mut w = flat_world();
        w.grant_spell(SpellId(2));
        // ⚖ LAY THE BOOK OUT **BELOW** THE CARPET (round 162, w162a).
        // The cast phase is slot-relative — arm at the carpet's walk
        // slot, fire at the token's, one ascending pass — so a token
        // BELOW the carpet is only reached on the NEXT lap, which is
        // the two-phase shape this test's mc1l48 t=4899 citation
        // records (retail's `+48` back at 251, re-armed, not fired).
        // Re-seating the carpet above the granted book reproduces that
        // layout; without it the tokens sit above the carpet and the
        // burst ends in the same tick instead.
        reseat_carpet_above(&mut w);
        let cost = crate::mc1::spells::SPELLS[2].possess_mana;
        // The intrinsic base pool IS one cast (both are 1000), and the
        // ceiling is re-censused every tick from claimed entities, so
        // an unclaimed test world can never fund a second re-arm —
        // which makes this world the sharpest probe there is: before
        // the fix the hold stayed at 3.0 forever on an empty pool.
        assert_eq!(w.player.mana, cost, "base pool funds exactly one arm");
        w.tick(
            away(),
            PlayerCommand {
                equip_left: Some(SpellId(2)),
                ..Default::default()
            },
        );
        let fwd = PlayerCommand {
            fire_left: true,
            ..Default::default()
        };
        w.tick(away(), fwd);
        assert_eq!(w.accel_override(), Some(3.0), "the cast tick channels");
        assert!(
            w.player.mana_delta > 0,
            "the cast command itself no longer debits — the TOKEN's \
             full-tick arm stamps it (retail's :64942-52 site)"
        );

        // The token's full-tick arm stamps the debit and the wizard
        // pass applies it the same frame, emptying the pool. The held
        // re-arm this tick still passes — retail's :55890 gate reads
        // the PRE-step pool (the mc1l32 t=671 law) — so the hold
        // survives the emptying tick at 3.0.
        w.tick(away(), fwd);
        assert_eq!(w.player.mana, 0, "the held tick actually spent the pool");
        assert_eq!(
            w.accel_override(),
            Some(3.0),
            "the re-arm gate reads the pre-step pool — 3.0 survives one tick"
        );

        // Now BOTH gates read the dry pool: the token refuses its
        // full tick (no debit, no sustain) and the re-arm is silently
        // refused — the burst keeps propelling at 2.0 rather than
        // cancelling, and the hold is over.
        w.tick(away(), fwd);
        assert_eq!(
            w.accel_override(),
            Some(2.0),
            "an unaffordable re-arm falls back to the 2.0 glide"
        );
        assert_ne!(w.player.accel, 0, "exhaustion does not cancel the channel");

        // And it stays refused while the pool is short of the FULL
        // cost — no partial-price 3.0. (Mid-burst suppression pins
        // the pool: regen cannot refund an arm while the burst lives.)
        for _ in 0..4 {
            w.tick(away(), fwd);
            assert_eq!(w.accel_override(), Some(2.0), "still unaffordable");
            assert!(w.player.mana < cost, "regen has not refunded an arm yet");
        }
    }

    /// The regen-rate select honors the caller's PRE-move probe and
    /// never re-probes the settled pose: retail reads bool1 once at
    /// :55345-52, before the carpet moves, and feeds both regen rates
    /// from it (:55407-16). mc1l0 t=2428 is the receipt: the carpet
    /// slid past the level-1 castle's summed extent on the tick its
    /// upgrade ball landed — the pre-move read keeps the castle rate,
    /// a post-move re-probe dropped to the floor for one tick.
    #[test]
    fn the_regen_select_honors_the_premove_probe_not_the_settled_pose() {
        use crate::mc1::mobs::MobCtx;
        let ctx = |px: u16, py: u16| MobCtx {
            px,
            py,
            pz: 100,
            pyaw: 0,
            pmana: 0,
            pmana_max: 0,
            pdead: false,
            pdead_top: false,
            strict: false,
            patches: crate::patches::WorldPatches::RETAIL,
            mc2_turn: 0,
        };
        let mut w = flat_world();
        w.player.mana = 0;
        w.player.mana_delta = 0;

        // Probe said at-castle; the settled pose (and the world — no
        // castle exists) says otherwise. A re-probe would floor it.
        w.mc1_wizard_pass(
            true,
            (false, false),
            PlayerCommand::default(),
            away(),
            &ctx(200 << 8, 200 << 8),
            (true, false),
        );
        assert_eq!(
            w.player.mana_delta, 1000,
            "pre-move TRUE selects castle rate"
        );

        // The mirror: a castle stands right under the settled pose,
        // but the pre-move probe said NO. A re-probe would boost it.
        let c = w.g.spawn_class3(2, 100 << 8, 100 << 8, 100).unwrap();
        w.g.ent[c].id24 = PLAYER_TARGET;
        assert!(
            w.player_castle().is_some(),
            "fixture: the castle resolves as the player's"
        );
        w.mc1_wizard_pass(
            true,
            (false, false),
            PlayerCommand::default(),
            away(),
            &ctx(100 << 8, 100 << 8),
            (false, false),
        );
        assert_eq!(w.player.mana_delta, 100, "pre-move FALSE keeps the floor");
    }

    #[test]
